INSERT INTO trails (id,icon,name,cnct_label,color,description,descricao_geral) VALUES
('trl-01','⚡','Eletrotécnica Industrial do Zero','#7 Eletrotécnica Industrial','#fcd34d','Do nivelamento básico até qualificação técnica em BT/MT e proteção de sistemas elétricos.',NULL),
('trl-02','🤖','Programador de CLP / Automação','#2 Automação Industrial','#818cf8','Do zero ao programador de CLP multi-marca. Ferramentas gratuitas dos fabricantes líderes.',NULL),
('trl-03','🔥','Soldagem Profissional','#22 Soldagem','#fb923c','Qualificação completa em soldagem: do básico ao offshore e certificação por norma.',NULL),
('trl-04','☀️','Energia Solar Fotovoltaica','#17 Transição Energética','#fbbf24','Para técnicos de elétrica e automação migrando para solar fotovoltaico.',NULL),
('trl-05','🔬','Inspeção e END Industrial','#13 Metalurgia / END','#34d399','Do nivelamento em PT à certificação international em ensaios não destrutivos.',NULL),
('trl-06','🦺','Segurança do Trabalho Industrial','#25 Segurança do Trabalho','#f87171','Do básico de NRs ao PSM avançado — cobre NR-10, NR-13, HAZOP e offshore.',NULL),
('TRL-AUT-014',NULL,'Trilha do Profissional em Automação Industrial','Automação e Controle de Processos',NULL,'Capacita o egresso para projetar, operar e manter sistemas automatizados, integrando instrumentação, controle, redes industriais e segurança funcional, com base em padrões ISA, IEC e boas práticas de engenharia.',NULL),
('TRL-MEC-015',NULL,'Trilha do Profissional em Válvulas e Bombas Industriais','Mecânica de Manutenção e Projetos',NULL,'Capacita o egresso para selecionar, operar e manter bombas e válvulas industriais, com base em normas API, ASME e boas práticas de engenharia de fluidos, incluindo dimensionamento, selagem e análise de falhas.',NULL),
('TRL-INSP-016',NULL,'Trilha do Profissional em Inspeção e Ensaios Não Destrutivos','Inspeção e Qualidade Industrial',NULL,'Capacita o egresso para realizar inspeções e ensaios não destrutivos em equipamentos industriais, estruturas e soldas, com base nas normas A SME, API, AWS e procedimentos da ASNT, garantindo a integridade e segurança operacional.',NULL),
('TRL-OPL-017',NULL,'Trilha do Profissional em Operações Offshore','Operação e Manutenção Offshore',NULL,'Capacita o egresso para atuar em plataformas offshore, com preendendo projeto estrutural, sistemas de ancoragem, dutos submarinos, integridade de equipamentos e segurança operacional, com base em normas ISO, API e DNV.',NULL),
('TRL-SEG-018',NULL,'Trilha do Profissional em Segurança Industrial e de Processos','Segurança e Saúde no Trabalho',NULL,'Capacita o egresso para gerenciar riscos ocupacionais e de processo, aplicando normas regulamentadoras (NRs), metodologias de análise de risco (HAZOP, LOPA, SIL) e planos de resposta a emergências, com base em padrões nacionais e internacionais.',NULL),
('TRL-DIG-019',NULL,'Trilha do Profissional em Tecnologia Digital para Indústria 4.0','Sistemas Digitais e Automação',NULL,'Capacita o egresso para aplicar tecnologias digitais na indústria, como gêmeos digitais, IoT, manutenção preditiva, simulação de processos, e segurança cibernética industrial (IEC 62443), integrando hardware e software em ambientes de produção.',NULL),
('TRL-TRANS-020',NULL,'Trilha do Profissional em Transição Energética e Energias Renovávei s','Energias Renováveis e Sustentabilidade',NULL,'Capacita o egresso para atuar no planejamento, implantação e operação de sistemas de energias renováveis (solar, eólica, biomassa, hidrogênio verde), integrando eficiência energética, políticas públicas (RenovaBio, PTE) e sustentabilidade, com base em atlas setoriais e normas técnicas.',NULL),
('TRL-REG-021',NULL,'Trilha do Profissional em Regulação Setorial e Compliance','Gestão Pública e Regulação',NULL,'Capacita o egresso para atuar na gestão pública e regulaçã o de setores estratégicos (petróleo, energia, mineração, portos, meio ambiente), a plicando normas da ANP, ANEEL, ANM, ANTAQ, CONAMA e procedimentos de licenciament o, com foco em governança, compliance e transparência.',NULL),
('TRL-QUIM-022',NULL,'Trilha do Profissional em Química e Petroquímica','Processos Químicos e Petroquímicos',NULL,'Capacita o egresso para atuar em indústrias químicas e pet roquímicas, compreendendo a cadeia produtiva (1ª, 2ª e 3ª geração), processos de t ransformação (craqueamento, reforma, polimerização), normas técnicas (ABNT NBR 147 25/ISO 20815/ISO 28300), segurança de processo e inovação tecnológica.',NULL),
('TRL-INS-023',NULL,'Trilha do Profissional em Instrumentação Industrial','Instrumentação e Controle de Processos',NULL,'Capacita o egresso para atuar na seleção, instalação, calibração e manutenção de instrumentos de campo (pressão, temperatura, nível, vazão, análise), integrando sistemas de controle, redes industriais e boas práticas de me trologia, com base em padrões ISA, fabricantes e normas de segurança.',NULL),
('TRL-LOG-024',NULL,'Trilha do Profissional em Logística e Operações Portuárias','Logística Portuária e Supply Chain',NULL,'Capacita o egresso para atuar na gestão de operações portu árias, logística de transporte, supply chain, movimentação de cargas, regulação po rtuária e comércio exterior, integrando conhecimentos de infraestrutura, seguranç a, meio ambiente e eficiência operacional.',NULL),
('TRL-MET-025',NULL,'Trilha do Profissional em Metrologia e Calibração','Metrologia e Garantia da Qualidade',NULL,'Capacita o egresso para atuar em laboratórios de calibração e metrologia, realizando medições, calibrações, gestão da rastreabilidade, controle de incerteza, e aplicação de normas ISO 17025 e procedimentos INMETRO, com foco em instrumentos dimensionais, elétricos, térmicos e de pressão.',NULL),
('TRL-SOL-026',NULL,'Trilha do Profissional em Soldagem e Caldeiraria','Soldagem, Caldeiraria e Integridade Estrutural',NULL,'Capacita o egresso para atuar em processos de soldagem, caldeiraria e inspeção de juntas soldadas, com domínio de técnicas de soldagem (MIG/MAG, TIG, eletrodo revestido, arco submerso), qualificação de soldadores (AWS/ASME), procedimentos de soldagem (WPS), metalurgia da solda, ensaios não destrutivos e gestão da integridade estrutural.',NULL),
('TRL-SIM-027',NULL,'Trilha do Profissional em Simulação de Processos Industriais','Simulação e Otimização de Processos',NULL,'Capacita o egresso para atuar na modelagem, simulação e otimização de processos industriais (refino, petroquímica, energia, utilidades), utilizando ferramentas computacionais gratuitas e comerciais, com foco em análise de sensibilidade, otimização de parâmetros, integração energética, e suporte',NULL),
('TRL-CIP-028',NULL,'Trilha do Profissional em Completação e Intervenção de Poços','Completação e Intervenção de Poços',NULL,'Capacita o egresso para atuar na completação e intervenção de poços de petróleo e gás, abrangendo projeto de completação, equipamentos de cabeça de poço, árvore de natal, workover, snubbing, coiled tubing e hydraulic workov er, com foco em segurança operacional, integridade de poços e boas pr',NULL),
('TRL-VAP-029',NULL,'Trilha do Profissional em Sistemas de Vapor e Geração Térmica','Sistemas Térmicos e Geração de Vapor',NULL,'Capacita o egresso para atuar na operação, manutenção e gestão de sistemas de geração e distribuição de vapor industrial, abrangendo caldeiras, trocadores de calor, utilidades térmicas, eficiência energética, segurança operacional (NR-13) e normas ASME, com foco em otimização de processos e sustentabilidade.',NULL),
('TRL-MOV-030',NULL,'Trilha do Profissional em Movimentação de Cargas e Içamento','Movimentação de Cargas e Içamento',NULL,'Capacita o egresso para atuar na operação segura de equipa mentos de movimentação e içamento de cargas (pontes rolantes, talhas, guindastes, pórticos, empilhadeiras), com domínio de acessórios (eslingas, grampos, manilhas), análise de riscos, cálculo de capacidade de carga, sinalização, manutençã',NULL),
('TRL-MICRO-001',NULL,'Micro-trilha: Gestão Pública para Iniciantes','Gestão Pública e Regulação',NULL,'Micro-trilha introdutória para profissionais que desejam compreender os fundamentos da administração pública, políticas públicas, orçamento e transparência, com base em cursos gratuitos da ENAP, EV.G e Aprenda Mais.',NULL),
('TRL-MICRO-002',NULL,'Micro-trilha: Simulação Computacional Aplicada','Simulação e Otimização de Processos',NULL,'Micro-trilha prática para profissionais que desejam aprender simulação de processos utilizando ferramentas open-source: NeqSim, DWSIM e Open FOAM, com foco em aplicações na indústria de óleo e gás, química e energia.',NULL),
('TRL-MICRO-003',NULL,'Micro-trilha: Indústria 4.0 para Técnicos','Sistemas Digitais e Automação',NULL,'Micro-trilha para técnicos que desejam compreender os conceitos e ferramentas da Indústria 4.0: IoT, análise de dados, manutenção preditiva e gêmeos digitais, com base em cursos gratuitos do SENAI Play, SENAI EAD e Futuro. Digital.',NULL),
('TRL-MICRO-004',NULL,'Micro-trilha: Segurança e Saúde no Trabalho (Básico)','Segurança e Saúde no Trabalho',NULL,'Micro-trilha introdutória para profissionais que desejam compreender os fundamentos de segurança e saúde no trabalho, com base em cursos gratuitos da Fundacentro, UNA-SUS e Fiocruz.',NULL),
('TRL-MICRO-005',NULL,'Micro-trilha: Ferramentas Digitais para Gestão','Gestão e Negócios (transversal)',NULL,'Micro-trilha para profissionais que desejam dominar ferram entas digitais aplicadas à gestão: produtividade, análise de dados, marketing digital e automação, com base em cursos gratuitos do Qualifica SP, Eu Capacito e Google Grow.',NULL),
('TRL-MOD-001',NULL,'Módulo: Regulação e Licenciamento de Eólica Offshore','Energias Renováveis e Sustentabilidade',NULL,'Módulo especializado sobre o arcabouço regulatório, licenciamento ambiental, normas técnicas e desafios setoriais para implantação de parques eólicos offshore no Brasil, com base na Lei 15.097/2025, ABEEólica, GWO e Ministério de Minas e Energia.',NULL),
('TRL-MOD-002',NULL,'Módulo: Otimização Energética de Sistemas Térmicos','Sistemas Térmicos e Geração de Vapor',NULL,'Módulo avançado para otimização de sistemas térmicos: pinc h analysis, integração energética, recuperação de calor, cogeração, e redução de perdas em plantas industriais.',NULL),
('TRL-MOD-003',NULL,'Módulo: Içamento de Cargas Superdimensionadas','Movimentação de Cargas e Içamento',NULL,'Módulo especializado para operações de içamento de cargas especiais: módulos offshore, equipamentos superdimensionados, estruturas pré-molda das, com foco em planejamento, cálculo, riscos e procedimentos de segurança.',NULL),
('TRL-MOD-004',NULL,'Módulo: Perfuração HPHT e Águas Ultraprofundas','Operação e Manutenção Offshore',NULL,'',NULL),
('TRL-MOD-005',NULL,'Módulo: Regulação e Compliance para Não-Juristas','Gestão Pública e Regulação',NULL,'Módulo introdutório para profissionais não-juristas sobre regulação setorial, compliance, licenciamento e transparência, com linguagem acess ível e casos práticos.',NULL),
('TRL-MOD-006',NULL,'Módulo: Soldagem de Materiais Não Ferrosos','Soldagem, Caldeiraria e Integridade Estrutural',NULL,'',NULL),
('TRL-SUB-001',NULL,'Sub-trilha: CLP Avançado — Programação Estruturada, ST e SFC','Automação e Controle de Processos',NULL,'Sub-trilha avançada para técnicos que desejam dominar linguagens de programação estruturada (ST), Sequential Function Chart (SFC) e boas práticas de engenharia de software para CLPs, com base em normas IEC 61131-3, manuais de fabricantes (Siemens, Rockwell, Schneider) e estudos de caso indus',NULL),
('TRL-SUB-002',NULL,'Sub-trilha: Redes Industriais — Profinet, Ethernet/IP e Segurança','Automação e Controle de Processos',NULL,'Sub-trilha para técnicos que desejam projetar, configurar e manter redes industriais baseadas em Profinet e Ethernet/IP, com foco em arquitetura, topologias, diagnóstico e cibersegurança (IEC 62443).',NULL),
('TRL-SUB-003',NULL,'Sub-trilha: Segurança Funcional (SIL) — IEC 61511 e SIS','Automação e Controle de Processos / Segurança Industria
