INSERT INTO cnct_courses (id,nome,eixo_tecnologico,carga_horaria_min,carga_dias_uteis,perfil_profissional,resumo_perfil,infraestrutura,resumo_infraestrutura,pagina_cnct,forcas_armadas,estagio_obrigatorio,nivel_regulamentacao,classificacao_industrial,categoria_industrial,profile_id,e_ancora,tier_csv,tier_ecosistema,label_tier_ecosistema,cobertura_guia,cobertura_guia_obs,setores_guia,bloco_fundamentos,trilhas_atlas,atlas_referencia,atlas_arquivo,status_atlas,palavras_chave,ofertado_forcas_armadas,principais_certificacoes,num_certificacoes,certificacoes_intermediarias,principais_especializacoes,num_especializacoes,especializacoes_tecnicas,principais_graduacoes,num_graduacoes,verticalizacao_graduacao,normas_associadas,micro_atlas_pdf) VALUES
(1,'Técnico em Controle Ambiental','Ambiente e Saúde',1200,150,'Propõe medidas para minimização dos impactos e recuperação de ambientes já degradados. Controla processos produtivos. Identifica o potencial poluidor de processos produtivos. Gerencia e monitora os processos de coleta, armazenamento e análise de dados ambiental em estações de tratamento de efluentes, afluentes e resíduos sólidos. Executa análises físico-químicas e microbiológicas destes. Avalia as intervenções antrópicas e utiliza tecnologias de prevenção, correção e monitoramento ambiental. Realiza levantamentos ambientais. Realiza campanhas de monitoramento e educação ambiental. Identifica tecnologias apropriadas para o processo de produção racional e cuidados com o meio ambiente. Opera sistemas de tratamento de poluentes e resíduos sólidos. Executa análises de controle de qualidade ambiental.','Propõe minimização de impactos; gerencia coleta/análise de dados; opera tratamento de efluentes e resíduos.','Biblioteca e videoteca com acervo específico e atualizado. Laboratório de informática com programas específicos. Laboratório de microbiologia. Laboratório de Análises Químicas.','Lab. informática, microbiologia, análises químicas.','18',0,'Não informado','Sim (Lei 12.305/10)','Industrial - Não abordado','Tier 0',34,0,'Tier 0','T5','Base Operacional Clássica','Baixa',NULL,'AMB|SAN|RES','MEIO AMBIENTE INDUSTRIAL','AMB1|AMB2|RES1|SAN1','Atlas de Meio Ambiente e Sustentabilidade','atlas_meio_ambiente_industrial_v1_0.md','Planejado','controle ambiental, efluentes, resíduos sólidos, tratamento, monitoramento, educação ambiental','Não','Operador de Aterro; Agente de Gestão de Resíduos; Agente de Limpeza Urbana',4,'Operador de Aterro Sanitário de Resíduos Sólidos Urbanos. Agente de Gestão de Resíduos Sólidos. Agente de Limpeza Urbana. Agente de Desenvolvimento Socioambiental.','Reciclagem; Gerenciamento Ambiental; Educação Ambiental',3,'Especialização técnica em reciclagem. Especialização técnica em gerenciamento ambiental. Especialização técnica em educação ambiental.','Tecnólogo em Meio Ambiente, Gestão Ambiental, Saneamento; Eng. Ambiental; Eng. Sanitária',5,'Curso superior de tecnologia em meio ambiente. Curso superior de tecnologia de gestão ambiental. Curso superior de tecnologia em saneamento ambiental. Bacharelado em engenharia ambiental. Bacharelado em engenharia sanitária.','Lei nº 12.305/2010. Decreto nº 7.404/2010.',NULL),
(2,'Técnico em Meio Ambiente','Ambiente e Saúde',1200,150,'Executa sistemas de gestão ambiental. Organiza programas de Educação ambiental com base no monitoramento, correção e prevenção das atividades antrópicas, conservação dos recursos naturais através de análises prevencionista. Organiza redução, reuso e reciclagem de resíduos e/ou recursos utilizados em processos. Identifica os padrões de produção e consumo de energia. Realiza levantamentos ambientais. Opera sistemas de tratamento de poluentes e resíduos sólidos. Relaciona os sistemas econômicos e suas interações com o meio ambiente. Realiza e coordena o sistema de coleta seletiva. Executa plano de ação e manejo de recursos naturais. Elabora relatório periódico das atividades e modificações dos aspectos e impactos ambientais de um processo, indicando as consequências de modificações.','Executa sistemas de gestão ambiental; organiza educação ambiental; opera tratamento de poluentes; coleta seletiva.','Biblioteca e videoteca com acervo específico e atualizado. Laboratório de informática com programas específicos.','Lab. informática','29',0,'Não informado','Sim (Leis 6.938/81, 12.305/10)','Industrial - Não abordado','Tier 0',35,1,'Tier 0','T5','Base Operacional Clássica','Baixa',NULL,'AMB|GES|REC','MEIO AMBIENTE INDUSTRIAL','AMB1|AMB2|GES1|GES2','Atlas de Meio Ambiente e Sustentabilidade','atlas_meio_ambiente_industrial_v1_0.md','Planejado','gestão ambiental, educação ambiental, tratamento de poluentes, coleta seletiva, redução, reuso, reciclagem','Não','Operador de Aterro, Agente de Gestão de Resíduos, Agente de Desenvolvimento Socioambiental',4,'Operador de Aterro Sanitário de Resíduos Sólidos Urbanos. Agente de Gestão de Resíduos Sólidos. Agente de Limpeza Urbana. Agente de Desenvolvimento Socioambiental.','Controle Ambiental, Tratamento de Efluentes, Gestão de Resíduos Sólidos',5,'Especialização técnica em controle ambiental. Especialização técnica em reciclagem. Especialização técnica em tratamento de efluente