INSERT INTO sector_codes (code,name,bloco,bloco_title,description) VALUES
('AUT','Automação e Controle','1-A','Automação de Processos, DCS e SCADA','Sistemas de controle distribuído (DCS), controladores lógicos programáveis (PLCs), SCADA, sistemas de gerenciamento de alarmes, HMI de processo, sistemas de execução de manufatura (MES) e segurança funcional (SIS/SIL — IEC 61511). Foco no engenheiro e técnico de automação que programa, configura e mantém os sistemas de nível de planta — perfil distinto do instrumentista de campo (Bloco 1-B).'),
('INS','Instrumentação','1-B','Instrumentação de Campo e Metrologia Industrial','Instrumentação de campo: medição de vazão, nível, pressão, temperatura e análise de processo. Calibração e metrologia industrial.'),
('DIG','Tecnologia Digital / Indústria 4.0','10-B','Digitalização Industrial, Gêmeos Digitais e Plataformas','Transformação digital industrial: gêmeos digitais, plataformas de dados operacionais (PI System), IIoT, MES e integração OT/IT. Indústria 4.0 e 5.0.'),
('ROT','Equipamentos Rotativos','2','Válvulas, Bombas, Fluidos, Vedação e Conexões','Equipamentos rotativos: bombas centrífugas e de deslocamento positivo, compressores, turbinas e sistemas de vedação mecânica.'),
('VLV','Válvulas e Conexões','2','Válvulas, Bombas, Fluidos, Vedação e Conexões','Válvulas industriais: controle, bloqueio, segurança e alívio. Seleção, dimensionamento e manutenção.'),
('VAP','Sistemas de Vapor','2','Válvulas, Bombas, Fluidos, Vedação e Conexões','Sistemas de vapor: geração, distribuição, purgadores, recuperação de condensado e eficiência energética.'),
('INT','Integridade e Inspeção','4-B','Integridade de Ativos, RBI e Gestão de Risco','Integridade de ativos industriais: corrosão, degradação, inspeção baseada em risco e planos de manutenção preditiva.'),
('END','Ensaios Não Destrutivos','4-A','Ensaios Não Destrutivos: Técnicas e Qualificação','Ensaios Não Destrutivos: Técnicas e Qualificação'),
('SOL','Soldagem e Caldeiraria','19','Soldagem Industrial e Qualificação de Procedimentos','Processos de soldagem industrial (SMAW, GMAW, GTAW, FCAW, SAW), metalurgia aplicada à soldagem, qualificação de procedimentos de soldagem (EPS/RQPS — ASME Sec. IX, AWS D1.1), qualificação de soldadores (CQ — conforme ABNT NBR 14842 e ASME Sec. IX), inspeção de soldas e soldagem em ambientes especiais (offshore, áreas classificadas, subaquática).'),
('SEG','Segurança Industrial e do Trabalho','8','Segurança, Salvatagem, Proteção Respiratória e Incêndio','Segurança industrial e do trabalho: NRs aplicadas, análise de risco, PSM/SMS, segurança de processo (IEC 61511/61508) e gestão de emergências.'),
('SAL','Salvatagem e Segurança Marítima','8','Segurança, Salvatagem, Proteção Respiratória e Incêndio','Salvatagem marítima, sobrevivência offshore, resgate aquático e operações de emergência em plataformas e embarcações.'),
('AMB','Meio Ambiente e Sustentabilidade','8','Segurança, Salvatagem, Proteção Respiratória e Incêndio','Meio ambiente e sustentabilidade: gestão ambiental, legislação ambiental, tratamento de efluentes e descarbonização industrial.'),
('LOG','Logística e Portos','LOG','Logística Industrial, Supply Chain e Suprimentos','Logística Industrial, Supply Chain e Suprimentos'),
('GES','Gestão, Projetos e Supply Chain','LOG','Logística Industrial, Supply Chain e Suprimentos','Logística Industrial, Supply Chain e Suprimentos'),
('REG','Regulatório e Jurídico','13','Regulatório, Direito Marítimo e RH Offshore','Regulatório industrial: ANP, ANEEL, NRs, legislação marítima (MARPOL, SOLAS), conformidade e direito offshore.'),
('PER','Perfuração e Geologia','9','Perfuração, Sondas, Geologia e Exploração','Perfuração onshore e offshore: fluidos de perfuração, cimentação, completação básica, geologia de reservatórios e exploração.'),
('ENE','Transição Energética e Hidrogênio','12-A','Transição Energética, Hidrogênio Verde e CCUS','Transição energética: hidrogênio verde, CCUS, descarbonização industrial, biocombustíveis, eólica e solar. Mercado de carbono e ESG industrial.'),
('QUI','Química e Petroquímica','14','Refino, Petroquímica e Processos Downstream','Refino, Petroquímica e Processos Downstream'),
('MOV','Movimentação de Cargas','5','Engenharia Offshore, Construção, Dutos e Comissionamento','Movimentação de cargas: equipamentos de içamento, operações de guindaste offshore, rigging e segurança em operações de carga.'),
('CIB','Cibersegurança Industrial','10-C','Cibersegurança Industrial OT/ICS','Cibersegurança industrial: proteção de sistemas OT/ICS, IEC 62443, NIST CSF para ambientes industriais e redes de controle.'),
('EDU','Educação e Qualificação','EDU','Educação, Qualificação e Formação Técnica Industrial','Educação, Qualificação e Formação Técnica Industrial'),
('OPR','Operação de Produção e Processo','16','Operação de Produção e Processo','Operação de plantas de processo em plataformas (FPSO, semi-submersíveis, fixas), refinarias e unidades de processamento de gás — incluindo sala de controle, operação de campo, separadores, compressores, trocadores e sistemas de utilidades.'),
('ELE','Elétrica Industrial e Acionamentos','17','Elétrica Industrial, Acionamentos e Proteção','Motores elétricos, inversores de frequência (VFD), acionamentos, proteção de sistemas elétricos, subestações industriais, NR-10 (Segurança em Instalações e Serviços em Eletricidade), áreas classificadas (ATEX/NEC 500/505) e eficiência energética em sistemas elétricos industriais.'),
('GCM','Gestão de Ativos e Confiabilidade','18','Gestão de Ativos, Confiabilidade e Manutenção','Engenharia de confiabilidade (RCM/MCC), inspeção baseada em risco (RBI), análise de falhas (FMEA/RCFA), planejamento e controle de manutenção (PCM), gestão de ativos (ISO 55001), indicadores de desempenho (MTBF, MTTR, OEE) e SAP PM — aplicados ao contexto de plantas de processo, equipamentos rotativos e infraestrutura offshore.'),
('EOL','Eólica Offshore e Energias Marinhas','20','Eólica Offshore e Energias Marinhas','Tecnologia de turbinas eólicas offshore (fundações, aerogeradores, nacelle, cabos submarinos), instalação e comissionamento de parques eólicos offshore, operação e manutenção (O&M) de turbinas no mar, certificações de segurança GWO (Global Wind Organisation), mercado e regulação de eólica offshore no Brasil e no mundo.'),
('CIP','Completação e Intervenção de Poços','21','Completação e Intervenção de Poços','Completação de poços (design de string, canhoneio, packers, caminhos de produção), intervenção de poços sem sonda (wireline elétrico, slickline, coiled tubing), workover com sonda, integridade de poços (well integrity — barreira primária e secundária), estimulação (acidificação, fraturamento hidráulico), abandono de poços e regulação ANP para intervenções.'),
('SIM','Simulação e Modelagem de Processos','10-A','Engenharia de Simulação e Software de Processo','Engenharia de Simulação e Software de Processo'),
('RBI','Inspeção Baseada em Risco e Integridade','4-B','Integridade de Ativos, RBI e Gestão de Risco','Inspeção baseada em risco (RBI): metodologia API 580/581, análise de consequências e definição de intervalos de inspeção.'),
('MET','Metrologia e Calibração Industrial','1-B','Instrumentação de Campo e Metrologia Industrial','Metrologia e calibração industrial: rastreabilidade, padrões de referência, laboratórios de calibração e incerteza de medição.');
