INSERT INTO atlas_trail_detail (id,trail_id,nivel,nivel_num,perfil_saida,curriculo,carga_estimada,normas_ref,fontes_abertas,criado_em) VALUES
(1,35,'Iniciante · Perfil de entrada: Qualquer técnico industrial ou estudante de curso técnico',1,'Opera processos básicos de soldagem (eletrodo revestido, MIG/MAG) com segurança','Princípios físicos da soldagem · Segurança em ambiente de soldagem (EPIs, proteção contra radiação, gases) · Processo Eletrodo Revestido (SMAW) — fundamentos e prática · Processo MIG/MAG (GMAW) — fundamentos e parâmetros · Identificação de descontinuidades visuais · Leitura básica de WPS (Welding Procedure Specification)',NULL,'["NR-34", "ABNT NBR 14842", "AWS A3.0"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(2,36,'Iniciante · Perfil de entrada: F1 concluído ou equivalente',1,'Interpreta desenhos técnicos industriais e simbologia de soldagem conforme AWS A2.4 e ISO 2553','Projeções ortogonais e vistas · Cotas e tolerâncias dimensionais · Simbologia de soldagem (AWS A2.4 e ISO 2553) · Leitura de isométricos de tubulação · Desenho assistido por computador básico (CAD viewer) · Interpretação de joint design em desenhos de montagem',NULL,'["AWS A2.4", "ABNT NBR 10067", "ISO 2553", "ABNT NBR 8402"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(3,37,'Pleno · Perfil de entrada: F1 + F2 concluídos',2,'Seleciona materiais metálicos para aplicações industriais, interpreta certificados de material e identifica aços carbono e aços-liga por norma','Estrutura cristalina dos metais · Diagrama ferro-carbono · Classificação de aços (carbono, baixa liga, inoxidáveis) · Normas de material: ASTM, ASME, DIN, ABNT NBR · Certificados de inspeção de material (Mill Certificate) · Propriedades mecânicas: tração, dureza, tenacidade, fadiga · Ligas não ferrosas de interesse industrial (alumínio, cobre, níquel)',NULL,'["ISO 3766", "ABNT NBR 7007", "ASME SA-516"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(4,38,'Pleno · Perfil de entrada: M1 concluído',2,'Especifica e acompanha tratamentos térmicos de pré e pós-soldagem (PWHT), prepara e analisa amostras metalográficas','Fundamentos de tratamentos térmicos (recozimento, normalização, têmpera, revenimento) · Pré-aquecimento e temperatura de interpasse em soldagem · PWHT (Post Weld Heat Treatment) — requisitos e procedimentos · Dureza Brinell, Rockwell e Vickers — aplicação prática · Preparação de corpo de prova metalográfico · Análise de microestrutura: grão, fases, ZTA (Zona Termicamente Afetada) · Correlação microestrutura-propriedades mecânicas',NULL,'["ABNT NBR 6118", "ASME B31", "AWS D1.1"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(5,39,'Pleno · Perfil de entrada: F2 + M1 concluídos',2,'Executa e documenta inspeção dimensional de estruturas soldadas, opera instrumentos de medição dimensional e emite relatórios de conformidade','Instrumentos de medição: paquímetro, micrômetro, relógio comparador, esquadro, nível de bolha · Tolerâncias de fabricação e montagem em soldagem · Distorção e empeno em juntas soldadas — medição e controle · Gabaritos e dispositivos de montagem · Inspeção dimensional de tubulações soldadas (alinhamento, perpendicularidade) · Rastreabilidade metrológica e calibração de instrumentos',NULL,'["ASME B16", "ISO 1101", "AWS D1.1"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(6,40,'Pleno · Perfil de entrada: F1 + F2 + M1 concluídos',2,'Aplica os principais métodos de END (VT, PT, MT, UT básico) em juntas soldadas, classifica descontinuidades conforme norma e emite laudos de aceitação/rejeição','Inspeção Visual (VT) — procedimentos e critérios de aceitação · Líquido Penetrante (PT) — fundamentos e aplicação · Partícula Magnética (MT) — fundamentos e aplicação · Ultrassom (UT) básico — princípios físicos e instrumentação · Radiografia Industrial (RT) — conceitos e segurança radiológica · Qualificação e certificação de pessoal END (SNT-TC-1A, ABENDI) · Critérios de aceitação: AWS D1.1, ASME B31.3, API 1104 · Documentação: relatórios de END, mapa de descontinuidades',NULL,'["ISO 9712", "API 1104", "AWS D1.1", "ASME B31", "ABNT NBR 16450"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(7,41,'Pleno · Perfil de entrada: F1 + F2 concluídos, experiência prática em SMAW',2,'Opera processos TIG, MIG/MAG e plasma em aços inoxidáveis e ligas especiais, seleciona parâmetros e consumíveis conforme WPS','Processo TIG (GTAW) — equipamentos, tungstênios, gases de proteção, técnica orbital · Processo MIG/MAG (GMAW) — transferência metálica (curto-circuito, globular, spray, pulsado) · Soldagem de aços inoxidáveis austeníticos e duplex · Soldagem de alumínio e suas ligas · Processo Plasma (PAW) — fundamentos e aplicações industriais · Arco Submerso (SAW) — automação e produtividade em estaleiros e caldeiraria · Soldagem dissimilar — desafios metalúrgicos e soluções · Gás de proteção — seleção de misturas para cada aplicação',NULL,'["ASME SFA-5", "ISO 15609", "ABNT NBR 14842", "AWS A5."]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(8,42,'Avançado · Perfil de entrada: P1 concluído',3,'Opera e programa células de soldagem automatizada e robótica, interpreta e ajusta parâmetros de WPS para processos automatizados','Princípios de automação em soldagem — por que e quando automatizar · Soldagem mecanizada vs. automatizada vs. robótica · Programação básica de robôs de soldagem (teach pendant) · Sensores e sistemas de visão em soldagem robótica · Adaptação de WPS para processos automatizados · Manutenção preventiva de células robóticas de soldagem · Cobótica em soldagem (Indústria 5.0) — colaboração humano-robô · Soldagem orbital automatizada em tubulações',NULL,'["AWS D16.1", "ISO 9283", "IEC 61800"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(9,43,'Avançado · Perfil de entrada: M1 + M2 + A7 concluídos',3,'Identifica e classifica mecanismos de corrosão em estruturas soldadas, especifica sistemas de proteção catódica e revestimentos anticorrosivos para ambientes industriais','Eletroquímica da corrosão — fundamentos e mecanismos · Tipos de corrosão: galvânica, por frestas, por pites, sob tensão (CSCC), intergranular · Corrosão em soldas: sensitização, HAZ corrosion, weld decay · Proteção catódica: anodo de sacrifício e corrente impressa — princípios · Revestimentos orgânicos e inorgânicos — seleção e especificação · Preparação de superfície (grau Sa, St conforme ISO 8501) · Inspeção de revestimentos: espessura de filme seco, aderência, holiday test · Gestãode integridade de dutos e estruturas metálicas em ambiente agressivo',NULL,'["ISO 8501", "ABNT NBR 14847", "ABNT NBR 6118", "ABNT NBR 7287"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(10,44,'Avançado · Perfil de entrada: F1 + F2 + P1 + A7 concluídos',3,'Elabora, qualifica e acompanha WPS/PQR/WPQ conforme ASME IX, AWS D1.1 e normas de tubulação industrial. Atua como Inspetor de Soldagem Nível 1 (preparação para certificação AWS CWI)','Estrutura do sistema de qualificação em soldagem (ASME Seção IX) · WPS — Welding Procedure Specification: variáveis essenciais e não essenciais · PQR — Procedure Qualification Record: ensaios de qualificação · WPQ/WPQT — qualificação de soldadores · Códigos de aplicação: AWS D1.1 (estruturas de aço), ASME B31.3 (tubulações), API 1104 (dutos) · Inspeção de soldagem: antes, durante e após · Registro e rastreabilidade de juntas soldadas · Preparação para certificação CWI (Certified Welding Inspector — AWS)',NULL,'["ISO 15614", "API 1104", "ASME BPVC Seção", "AWS D1.1", "AWS D1.6", "ASME B31", "ASME Seção IX", "AWS CWI", "ABNT NBR 14842", "ASME IX"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(11,48,'Iniciante · Perfil de entrada: Qualquer trabalhador industrial ou estudante de curso técnico',1,'Conhece a estrutura legal da SST brasileira, identifica quais NRs se aplicam à sua função e ao seu setor, e entende os direitos e obrigações do trabalhador, do empregador e do técnico de segurança','Estrutura das Normas Regulamentadoras (NRs) — histórico e hierarquia legal · NR-1 (Disposições Gerais e PGR) — a NR que organiza todas as outras · NR-4 (SESMT) — dimensionamento, obrigações e responsabilidades do técnico de segurança · NR-5 (CIPA) — composição, eleição e funcionamento · NR-6 (EPIs) — sistema de CA, responsabilidades do empregador e do trabalhador · NR-7 (PCMSO) — interface com a medicina do trabalho · NR-9/PGR (PPRA/Programa de Gerenciamento de Riscos) — a mudança de 2021 e o que mudou na prática · Acidente de trabalho — conceito legal, CAT, nexo causal e obrigações · Insalubridade e periculosidade (NR-15 e NR-16) — como calcular e comprovar · Responsabilidade civil e criminal do técnico de segurança — o que a Lei 7.410/1985 garante e o que cobra','40–60 horas','["NR-5", "NR-15", "NR-6", "NR-16", "NR-7", "NR-4", "NR-1", "NR-9"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(12,49,'Iniciante · Perfil de entrada: F1 concluído ou equivalente',1,'Seleciona, especifica, inspeciona e gerencia EPIs para ambientes industriais de O&G, identifica e classifica riscos ocupacionais segundo a hierarquia de controles, e elabora APRs (Análise Preliminar de Riscos)','Hierarquia de controles de risco: eliminação > substituição > controles de engenharia > controles administrativos > EPIs · Classificação dos riscos ocupacionais: físicos, químicos, biológicos, ergonômicos, mecânicos/acidentes · EPIs críticos em O&G: proteção respiratória (máscaras filtrantes, SCBA, linha de ar), detecção de gases (portáteis e fixos), proteção contra quedas, proteção ocular e auricular · Certificado de Aprovação (CA): como consultar e o que ele garante — e o que não garante · SCBA (Self-Contained Breathing Apparatus): tipos, uso, manutenção e limitações · Limites de exposição: TLV-TWA, TLV-STEL, TLV-C, IDLH — o que cada valor significa na prática · Análise Preliminar de Riscos (APR): elaboração, critérios de probabilidade × severidade e medidas de controle · Permissão de Trabalho (PT): estrutura, preenchimento, responsabilidades e conflitos de operação simultânea','50–70 horas','["NR-15", "NR-6", "ABNT NBR 10898", "NR-9"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(13,50,'Pleno · Perfil de entrada: F1 + F2 concluídos',2,'Planeja, supervisiona e habilita trabalhos em altura em estruturas industriais e offshore — seleciona e inspeciona sistemas de proteção contra quedas — elabora planos de resgate e conduz treinamentos de equipes de campo','NR-35 completa: obrigações, habilitação, treinamento e periodicidade · Sistemas de proteção contra quedas: pontos de ancoragem, cinturões, talabartes, absorvedores de energia e linhas de vida · Trabalho em superfícies inclinadas, estruturas metálicas e tubulações suspensas · Plano de Resgate: obrigatoriedade, elaboração e simulações práticas · Trabalho em andaimes, plataformas elevatórias e suspensas · Normas internacionais: ANSI Z359 (família completa) e EN 363 — como se comparam com a NR-35 · Especificidades offshore: trabalho em estruturas de plataformas, cruzeiros de tubulação a altura marítima e inspeção de risers a altura · Cálculo de comprimento total da linha de vida — a falha mais comum em bancas de inspeção','60–80 horas','["ABNT NBR 15475", "NR-35", "ABNT NBR 14629"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(14,51,'Pleno · Perfil de entrada: F1 + F2 concluídos',2,'Supervisiona e coordena trabalhos em espaços confinados em ambientes industriais de O&G — executa avaliação de atmosfera — gerencia o sistema de permissão de trabalho para espaços confinados — planeja resgates e lidera treinamentos de equipes de entrada e vigias','NR-33 completa: classificação de espaços, obrigações do empregador, funções (vigia, supervisor, trabalhador autorizado) e requisitos de treinamento · Avaliação e monitoramento de atmosfera: oxigênio (mínimo 19,5%, máximo 23,5%), gases inflamáveis (LEL%), H₂S, CO, CO₂ e vapores de hidrocarbonetos · Equipamentos de detecção para NR-33: detectores multigas, draegertubes, sensores catalíticos e eletroquímicos · Controle de energia (isolamento e bloqueio) antes da entrada — lockout/tagout em espaços confinados · Permissão de Trabalho específica para espaço confinado: variáveis, validade e cancelamento · Plano de Resgate: técnicas, equipamentos e limitações — quando não entrar · Espaços confinados em O&G: tanques de teto flutuante, vasos de processo, esgotadores, risers internos, porões de plataformas FPSO · Referências internacionais: OSHA 29 CFR 1910.146 e EN 15258 — como se comparam com a NR-33','60–80 horas','["ABNT NBR 16026", "NR-33"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(15,52,'Pleno · Perfil de entrada: F1 + F2 concluídos — noções básicas de eletricidade (desejável)',2,'Supervisiona trabalhos em instalações elétricas industriais com base na NR-10 — entende os requisitos do Sistema Elétrico de Potência (SEP) e a habilitação adicional necessária — avalia riscos de arco elétrico — elabora PTs para trabalhos elétricos em plantas de O&G','NR-10 completa: estrutura, habilitação, treinamento e periodicidade de reciclagem · Riscos elétricos: choque elétrico, queimaduras por arco elétrico (arc flash), incêndio e explosão · Sistema Elétrico de Potência (SEP): habilitação adicional, diferenças em relação ao trabalho em baixa tensão · Distâncias de segurança: zona controlada e zona de risco conforme NR-10 · Energia perigosa e controle: LOTO (Lockout/Tagout) — NR-10 e NFPA 70E comparadas · Arco elétrico (arc flash): fundamentos, cálculo de incidente energético (cal/cm²), PPE elétrico por categoria · Áreas classificadas: relação entre NR-10 e NR-20 para instalações em plantas de O&G com vapores inflamáveis · Inspeção de instalações elétricas: critérios da ABNT NBR 5410 e documentação técnica exigida','60–80 horas','["ABNT NBR 5410", "ABNT NBR 14039", "IEC 60364", "NR-10", "NFPA 70"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(16,53,'Pleno · Perfil de entrada: F1 + F2 concluídos',2,'Entende os requisitos legais da NR-13 para vasos de pressão e caldeiras — verifica documentação de inspeção periódica — conhece os critérios de classificação de vasos e as categorias de risco — atua como interface entre a equipe de SST e os inspetores de equipamentos','NR-13 completa: classificação de caldeiras e vasos, requisitos de operação, inspeção periódica, documentação exigida e penalidades · Categorias de vasos de pressão (I a IV) — como classificar e o que muda em cada categoria · PMTA (Pressão Máxima de Trabalho Admissível): conceito e importância operacional · Documentação obrigatória: Prontuário de Vaso de Pressão, Registro de Segurança, ILPL · Responsabilidades do Técnico de Segurança na NR-13: o que compete ao TST e o que compete ao engenheiro de integridade · Critérios para interdição de equipamentos: quando e como o TST pode paralisar · Caldeiras: categorias, dispositivos de segurança (válvulas de alívio, manômetros, visor de nível), sala de caldeiras e requisitos de segurança · Vasos de pressão em O&G: separadores trifásicos, pulmões de ar de instrumentos, vasos de processo — os mais comuns que o TST encontrará','50–70 horas','["NR-13", "ABNT NBR 13031", "ASME BPVC Seção", "ABNT NBR 12177"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(17,54,'Avançado · Perfil de entrada: F1 + F2 + N2 concluídos (NR-33 prepara para atmosferas explosivas)',3,'Especifica e supervisiona sistemas de detecção de incêndio e gás em instalações industriais de O&G — entende a lógica de intertravamento F&G com sistemas de processo (ESD/PSD) — organiza brigadas industriais — analisa projetos de proteção contra incêndio conforme NFPA e normas brasileiras','Físico-química do fogo: triângulo e tetraedro do fogo, classes de incêndio, comportamento do fogo em hidrocarbonetos e GLP · Agentes extintores: água, CO₂, pó químico seco, espuma AFFF/FFFP, agentes limpos (HFC-227ea, FK-5-1-12) — quando usar cada um · Sistemas fixos de supressão: sprinklers ESFR, dilúvio, FM-200, CO₂ total flooding — aplicações industriais · Sistemas de detecção de gás: sensores IR, catalíticos, eletroquímicos e pontuais — integração em malha · Sistemas de detecção de chama: UV, IR, UV/IR — falsos alarmes e seleção por ambiente · Lógica de F&G em O&G: sistemas Fire & Gas (F&G) integrados com PSD (Process Shutdown) e ESD (Emergency Shutdown) — o que o TST precisa entender sem ser engenheiro de automação · NR-23 e NFPA: como as normas brasileiras e americanas se complementam · Brigada industrial: dimensionamento, treinamento e plano de emergência (PE) · PPCI (Plano de Prevenção Contra Incêndio): estrutura e obrigações por tipo de instalação','80–100 horas','["ABNT NBR 15808", "NR-33", "ABNT NBR 13714", "ABNT NBR 17240", "NFPA 10", "NR-23"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(18,55,'Avançado · Perfil de entrada: F1 + F2 concluídos',3,'Elabora o Programa de Gerenciamento de Riscos (PGR) conforme NR-1 (2021) — realiza e documenta reconhecimento, avaliação e controle de agentes físicos, químicos e ergonômicos — elabora laudos de insalubridade e periculosidade — integra PGR com PCMSO e o programa de medicina ocupacional','PGR (Programa de Gerenciamento de Riscos) conforme NR-1/2021: inventário de riscos, plano de ação, monitoramento e revisão · Agentes físicos: ruído (NR-15 Anexo 1 e NR-15 Anexo 2), calor, vibração, radiações não ionizantes (NR-15 Anexo 7) · Agentes químicos em O&G: hidrocarbonetos, H₂S, benzeno (carcinogênico — Portaria SSST 14/1995), aminas, NOx, SO₂ — limites de tolerância e controles · Benzeno: legislação específica (Acordo FIOH/Petrobrás 1995), PPEOB (Programa de Prevenção à Exposição Ocupacional ao Benzeno) · Ergonomia básica (NR-17): análise ergonômica do trabalho (AET), trabalho embarcado e fadiga offshore · Biometria ocupacional: coleta de dados para laudos de insalubridade e periculosidade (NR-15, NR-16) · LTCAT (Laudo Técnico das Condições Ambientais do Trabalho) — diferença do PPRA e quando é obrigatório · PCMSO interface: como o PGR alimenta os exames médicos periódicos e de mudança de função','80–110 horas','["NR-15", "NR-16", "NR-17", "ISO 45001", "NR-1", "NR-9"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(19,56,'Avançado · Perfil de entrada: F1 + F2 + N2 + N4 concluídos — experiência de campo em ambiente de processo é fortemente recomendada',3,'Entende os fundamentos do Process Safety Management (PSM) — participa ativamente de estudos HAZOP como secretário ou membro de equipe — compreende o conceito de Safety Integrity Level (SIL) e sua relação com os sistemas de intertravamento de segurança (SIS) — atua como TST em auditorias de segurança de processo','Process Safety Management (PSM): os 14 elementos do PSM conforme OSHA 29 CFR 1910.119 e API RP 750 · Identificação de perigos de processo: What-if, Checklist, FMEA, HAZOP — quando usar cada metodologia · HAZOP (Hazard and Operability Study): metodologia, palavras-guia, nós de estudo, desvios, causas, consequências e ações — como o TST participa · Análise de Camadas de Proteção (LOPA): fundamentos e interface com SIL · Safety Integrity Level (SIL) — IEC 61511: conceitos básicos que o TST de processo precisa entender · Sistemas de Intertravamento de Segurança (SIS): diferença entre controle de processo (BPCS) e intertravamento de segurança (SIS) · Gestãode mudanças (MOC — Management of Change): obrigações, formulários e o papel do TST na aprovação · Análise de causa raiz de acidentes de processo: metodologia Bow-Tie, Reason''s Swiss Cheese, MORT · Lições aprendidas: Texas City (2005), Piper Alpha (1988), Bhopal (1984) — o que cada acidente ensina ao TST de processo','100–140 horas','["ISO 45001", "IEC 61511", "IEC 61508"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(20,57,'Avançado · Perfil de entrada: F1 + F2 + N1 + N2 concluídos — experiência ou interesse em trabalho embarcado',3,'Domina as especificidades de segurança do ambiente offshore — entende os requisitos regulatórios marítimos (NORMAM, SOLAS, MARPOL) — planeja e supervisiona procedimentos de abandono de plataforma — é candidato qualificado para certificação HUET e OPITO Survival','Ambiente offshore: especificidades de risco de plataformas FPSO, semi-sub, fixas e jack-ups versus instalações onshore · SOLAS (Safety of Life at Sea): capítulos aplicáveis a plataformas, muster stations, MSDs (Muster and Drill procedures) · NORMAM-01/DPC (Marinha do Brasil): normas de segurança para embarcações e plataformas registradas no Brasil · Balsas salva-vidas, baleeiras e sistemas MES (Marine Evacuation System): tipos, operação e manutenção · HUET (Helicopter Underwater Escape Training): o que é, por que é obrigatório, como se preparar para o treinamento · OPITO Survival: estrutura do programa — BOSIET (Basic Offshore Safety Induction and Emergency Training) e FOET (Further Offshore Emergency Training) · EPIs específicos offshore: trajes de imersão (TPA/TSUE), coletes Classe I e SOLAS, luzes de socorro · Plano de Emergência de Plataforma: estrutura, funções, exercícios obrigatórios (fire drill, muster drill, man overboard) · GWO BST (Basic Safety Training): pré-requisito para trabalho em eólica offshore — base comum com a segurança de petróleo','80–100 horas','[]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(21,61,'Iniciante · Perfil de entrada: Qualquer estudante de ensino médio ou trabalhador técnico',1,'Domina os fundamentos de circuitos CA e CC — interpreta diagramas elétricos unifilares e esquemas de ligação — executa instalações de baixa tensão conforme ABNT NBR 5410 — conhece os critérios de proteção e dimensionamento de cabos, disjuntores e dispositivos DR/DPS','Grandezas elétricas: tensão, corrente, resistência, potência ativa, reativa e aparente, fator de potência · Lei de Ohm e leis de Kirchhoff — aplicações em circuitos industriais · Corrente alternada: fasores, impedância, ressonância e circuitos trifásicos equilibrados e desequilibrados · Sistemas de tensão no Brasil: 127/220 V e 220/380 V — implicações práticas para dimensionamento · ABNT NBR 5410 (BT) e NBR 14039 (MT): as duas normas que estruturam as instalações elétricas industriais no Brasil · Dimensionamento de cabos: critérios de capacidade de condução, queda de tensão, proteção contra curto-circuito e sobrecarga · Dispositivos de proteção: disjuntores termomagnéticos, DR (diferencial-residual), DDR e DPS (surtos) · Aterramento e equipotencialização: sistemas TN, TT, IT — critérios de aplicação em instalações industriais · Leitura de diagramas: unifilares, trifilares e esquemas de comando · Ferramentas de medição: multímetro, alicate amperímetro, megôhmetro e analisador de qualidade de energia — uso correto e interpretação','60–80 horas','["ABNT NBR 5410", "IEC 60364", "ABNT NBR 5456", "ABNT NBR 14039"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(22,62,'Iniciante-Pleno · Perfil de entrada: E1 concluído ou formação técnica básica em elétrica',1,'Possui habilitação básica NR-10 (ou está preparado para o treinamento formal) — entende os riscos elétricos, as distâncias de segurança e os procedimentos de bloqueio de energia (LOTO) — conhece os fundamentos do arco elétrico e os EPIs elétricos por categoria de risco — sabe quando é necessária a habilitação complementar SEP','NR-10 completa: estrutura, campo de aplicação, habilitação básica e complementar (SEP) · Riscos elétricos: choque elétrico (caminhos da corrente, limites fisiológicos, fatores agravantes), queimaduras por arco elétrico, incêndio e explosão por energia elétrica · Zonas de risco e controlada: distâncias conforme NR-10 Anexo I — o que o eletricista pode fazer em cada zona · Bloqueio de energia (LOTO — Lockout/Tagout): procedimento completo, dispositivos de bloqueio, cadeados e etiquetas · Trabalho sem tensão: procedimento dos 5 passos de segurança (secar, isolar, travar, verificar, aterrar) · Trabalho sob tensão em BT: condições, EPIs obrigatórios e ferramentas isoladas · Sistema Elétrico de Potência (SEP): o que diferencia o trabalho em SEP do trabalho em instalações BT comuns — habilitação complementar necessária · Arco elétrico (arc flash): física do fenômeno, incidente energético (cal/cm²), cálculo conforme IEEE 1584, categorias de PPE conforme NFPA 70E · EPIs elétricos: luvas de isolamento elétrico (classes), mantas, capacetes tipo II, óculos, protetor facial e roupas de proteção contra arco','40–60 horas','["ABNT NBR 5410", "NR-10", "ABNT NBR 14039", "NFPA 70"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(23,63,'Pleno · Perfil de entrada: E1 concluído',2,'Seleciona motores elétricos para aplicações industriais críticas (bombas, compressores, ventiladores, agitadores) — interpreta dados de plaqueta e curvas características — executa e supervisiona manutenção corretiva e preventiva de motores — entende as classes de isolamento, graus de proteção (IP) e classes de eficiência (IE)','Motor de indução trifásico (MIT): princípio de funcionamento, escorregamento, curva de conjugado, corrente de partida · Classes de eficiência energética: IE1, IE2, IE3 (Premium) e IE4 (Super Premium) — o que mudou com a ABNT NBR 17094-1 · Graus de proteção IP e IK: aplicação correta em ambientes industriais (IP55, IP65, IP66, IP67 — o que cada número significa) · Plaqueta de motor: interpretação completa — dados elétricos, mecânicos e de instalação · Partida de motores: partida direta (DOL), estrela-triângulo (Y-Δ), auto-transformador, soft starter e inversor de frequência — quando usar cada método e por quê · Manutenção de motores: termografia, análise de vibração, análise de isolamento (megôhmetro), limpeza e lubrificação de mancais · Motores especiais: motores para zona classificada (Ex d, Ex e, Ex n), motores de alta velocidade, motores de múltiplas velocidades e motores para aplicações submersas · Seleção de motor: critérios de potência, fator de serviço, ciclo de carga e condições ambientais · Motores de corrente contínua (CC) e brushless (BLDC/PMSM): aplicações em perfuração direcional e posicionamento offshore','70–90 horas','["ABNT NBR 17094", "IEC 60529", "IEC 60034"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(24,64,'Pleno · Perfil de entrada: E1 + M1 concluídos',2,'Seleciona, instala, parametriza e realiza manutenção de inversores de frequência (VFD/VSD) e soft starters para aplicações de bombeamento, compressão e transporte industrial — interpreta e diagnostica falhas de inversor — entende os critérios de dimensionamento de cabos e filtros associados','Princípio de funcionamento do inversor de frequência: retificador, barramento CC, inversor PWM, modulação de largura de pulso e filtros de saída · Controle escalar (V/f) versus controle vetorial (sensorless e com encoder): quando cada modo é adequado · Dimensionamento de inversores: relação com motor, fator de torque, ciclo de trabalho e corrente de pico · Parametrização básica e avançada: rampa de aceleração/desaceleração, limites de frequência, proteções e funções de processo (PID integrado) · Diagnóstico de falhas: decifrar os códigos de erro dos principais fabricantes (WEG CFW, ABB ACS, Danfoss VLT, Siemens G120, Schneider Altivar) · Instalação: comprimento máximo de cabo motor, filtros dV/dt e seno, EMC — como evitar interferência em redes industriais · Soft starter: princípio de funcionamento, parametrização e diferenças em relação ao inversor — quando é a escolha correta · Acionamentos de alta potência: topologias de média tensão (NPC, CHB), transformadores de tração e sistemas Multi-Drive · Aplicações offshore: acionamentos para compressores de injeção de gás, bombas de elevação artificial e sistemas de posicionamento dinâmico (thruster drives)','80–100 horas','["IEC 61800", "IEC 60034-17", "IEC 61800-5-1", "IEC 60947-4-2"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(25,65,'Avançado · Perfil de entrada: E1 + E2 + M1 concluídos',3,'Compreende a arquitetura de subestações industriais (QGBT, CLP, cubículos de MT, transformadores de força e instrumentos) — interpreta diagramas unifilares de subestações completas — realiza comissionamento básico e manutenção de rotina em equipamentos de MT — reconhece os critérios de dimensionamento e de seletividade de uma subestação industrial','Arquitetura de uma subestação industrial típica: entrada de concessionária (13,8 kV ou 34,5 kV), transformador de força, barramento de MT, cubículos de saída, QGBT de BT e MCC (Motor Control Center) · Transformadores de potência: relação de transformação, grupos de ligação (Dyn11, Yyn0), ensaios de comissionamento e manutenção preventiva · Transformadores de instrumentos (TCs e TPs): função, relação de transformação, classe de precisão e ligação em esquemas de proteção e medição · Sistemas de barra: barramento simples, duplo e com by-pass — critérios de escolha conforme criticidade · Disjuntores de MT: a vácuo e SF₆ — comparação, manutenção e testes de tempo de abertura · Religadores, seccionadoras e chaves de transferência automática (ATS): função e critérios de especificação · Sistemas de CC auxiliar: banco de baterias, carregador e barramento CC para proteção e controle — por que é crítico e como mantê-lo · Subestações offshore: arquitetura de plataformas (geração local, barramento de 6,6 kV e 690 V), sistemas de geração diesel/gás e qualidade de energia em ilhas elétricas · Aterramento de subestações: malha de aterramento, resistência de aterramento (< 1 Ω em subestações industriais críticas), ensaios e normas (ABNT NBR 15751, IEEE 80)','80–100 horas','["ABNT NBR 14039", "ABNT NBR 15751", "IEC 62271", "IEC 61439"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(26,66,'Avançado · Perfil de entrada: D1 concluído',3,'Entende os princípios de funcionamento e ajuste das principais funções de proteção elétrica (sobrecorrente, diferencial, distância, subtensão, frequência) — interpreta estudos de coordenação de proteção e ajuda a execução de relay settings — realiza análise básica de arco elétrico (arc flash) e determina categorias de PPE — participa de comissionamento de sistemas de proteção','Fundamentos de proteção elétrica: seletividade, rapidez, sensibilidade e confiabilidade — os quatro requisitos que todo sistema de proteção deve satisfazer · Funções de proteção ANSI/IEEE: 50/51 (sobrecorrente), 87 (diferencial), 21 (distância), 27/59 (sub/sobretensão), 81 (frequência), 46 (sequência negativa), 49 (temperatura de motor) · Proteção de transformadores: diferencial de transformador (87T), Buchholz, proteção de temperatura e relé de pressão repentina · Proteção de motores industriais: sobrecarga (49), curto-circuito (50/51), perda de fase (46), trava de rotor (48), subtensão (27) — e como cada falha danifica o motor · Coordenação de proteção: curvas tempo-corrente (TCC), software de coordenação (ETAP, SKM — fundamentos gratuitos) · Arco elétrico (arc flash): cálculo de incidente energético conforme IEEE 1584 (edição 2018), determinar rótulos de arco, categorias de PPE · Sistemas de proteção numérica (IED): introdução aos relés microprocessados, parametrização básica e comunicação SCADA · Automação de subestações com IEC 61850: o protocolo que está transformando as subestações digitais — fundamentos e aplicações em plantas de O&G','90–120 horas','["IEC 60255", "IEC 61850", "NFPA 70"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(27,67,'Avançado · Perfil de entrada: E1 + E2 + D1 concluídos',3,'Diagnostica e propõe soluções para problemas de qualidade de energia em plantas industriais (harmônicas, fator de potência, flicker, desequilíbrio de tensão, variações de frequência) — especifica bancos de capacitores e filtros de harmônicas — compreende o funcionamento e a manutenção de UPS industriais para cargas críticas de controle e segurança','Qualidade de energia: definição, impactos na produção (falhas em CLP, reinícios de motor, danos a transformadores) e custo real do problema · Harmônicas: origem (inversores, retificadores, lâmpadas LED, variadores), cálculo de THD (Total Harmonic Distortion), limites conforme IEEE 519 e ABNT NBR 16264 · Fator de potência: conceito, cálculo, impacto na conta de energia (cosφ < 0,92 gera penalidade no Brasil), bancos de capacitores fixos e automáticos · Desequilíbrio de tensão: causas (cargas monofásicas desbalanceadas), efeitos em motores (sobreaquecimento, redução de vida útil) e limites normativos · Flicker e variações rápidas de tensão: causas em soldadores e grandes motores, medição conforme IEC 61000-4-15 · UPS (Uninterruptible Power Supply) industrial: topologias (off-line, line-interactive, on-line dupla conversão), seleção para salas de controle e sistemas SIS/ESD · Baterias industriais: VRLA (AGM/GEL), Ni-Cd, Li-Ion — comparação, manutenção e testes de autonomia · Instrumentação de qualidade de energia: analisadores de rede, osciloscópios industriais, medidores de energia com registro','70–90 horas','["IEC 61000", "ABNT NBR 16264"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(28,68,'Avançado · Perfil de entrada: E1 + E2 + M2 concluídos',3,'Classifica ambientes conforme IEC 60079-10-1 (gases) e NEC 505/500 — especifica, inspeciona e verifica equipamentos com marcação Ex em instalações de O&G — entende os modos de proteção Ex (Ex d, Ex e, Ex ia/ib, Ex n, Ex t) — interpreta certificados ATEX e IECEx — realiza inspeções de manutenção em instalações Ex conforme IEC 60079-17','O que é uma área classificada: por que gases inflamáveis, poeiras combustíveis e vapores criam zonas de risco de explosão · Classificação de áreas conforme IEC 60079-10-1: Zona 0, Zona 1, Zona 2 (gases) e Zona 20, 21, 22 (poeiras) — como determinar a zona de uma área · NEC 500 e NEC 505: o sistema americano de classificação (Classe I Divisão 1/2 vs. Zona 1/2) — diferenças com o sistema IEC e quando cada um se aplica no Brasil · Temperaturas de ignição: Grupo de temperatura (T1 a T6) e Grupo de gás (IIA, IIB, IIC) — por que H₂ e C₂H₂ exigem equipamentos de maior categoria · Modos de proteção Ex: Ex d (carcaça antideflagrante), Ex e (segurança aumentada), Ex ia/ib (segurança intrínseca), Ex n (não faiscante), Ex p (pressurização), Ex t (proteção por carcaça — poeiras) — princípio de funcionamento e campo de aplicação de cada um · Marcação de equipamentos Ex: interpretação completa — II 2 G Ex d IIB T6 Gb IP66 ATEX/IECEx · Inspeção inicial, periódica e de amostragem de instalações Ex: conforme IEC 60079-17 — graus de inspeção (visual, próxima e detalhada) · NR-10 em áreas classificadas: o que a norma brasileira exige especificamente para o eletricista que trabalha em Zona 1','80–100 horas','["IEC 60079-11", "IEC 60079-1", "IEC 60079-0", "IEC 60079-17", "IEC 60079-7", "IEC 60079-10-1", "IEC 60079"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(29,69,'Avançado · Perfil de entrada: M1 + M2 concluídos',3,'Realiza diagnósticos energéticos em sistemas de acionamentos e bombeamento industrial — calcula e apresenta projetos de economia de energia com inversores de frequência — compreende a estrutura de um Sistema de Gestãode Energia (SGE) baseado em ISO 50001 — apoia processos de certificação e auditorias energéticas','Diagnóstico energético industrial: medição de consumo por sistema (compressores, bombas, ventiladores, iluminação, fornos), identificação de desperdícios e cálculo de payback · Curva do sistema versus curva do equipamento: entender por que um motor trabalhando longe do ponto de projeto consome muito mais energia · Economia com inversores de frequência em bombas centrífugas: lei da afinidade (P ∝ n³) — redução de 20% na velocidade = 49% de economia de energia · Compressores de ar e de gás: controle de capacidade com velocidade variável versus controle por válvula de estrangulamento — potencial de economia · ISO 50001: estruturada norma, linha de base energética, IDS (Indicadores de Desempenho Energético), plano de ação e revisão energética · Etiquetagem de eficiência energética no Brasil: PROCEL Indústria, INMETRO — como afeta a especificação de motores e transformadores · Tarifas de energia elétrica: estrutura tarifária (TUSD + TUST), custo de demanda, fator de potência — como cada um afeta a conta da planta · Projetos ESCO (Energy Service Company): modelo de negócio, contrato de performance e como o técnico eletrotécnico atua nesses projetos','60–80 horas','["ABNT NBR 17094", "ISO 50001"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(30,70,'Avançado · Perfil de entrada: D1 + D2 + M2 concluídos — experiência de campo em planta industrial é fortemente recomendada',3,'Compreende a arquitetura elétrica de plataformas FPSO e instalações offshore — entende os sistemas de geração e distribuição de energia em ilhas elétricas flutuantes — conhece os acionamentos de alta potência (MT) para compressores de produção e bombas de injeção — domina os requisitos de qualificação de sistemas elétricos para o ambiente marítimo (DNV, ABS, Lloyd''s)','Arquitetura elétrica de uma plataforma FPSO: geração (turbogeradores a gás, diesel de emergência), barramento de alta potência (6,6 kV ou 11 kV), transformadores de plataforma, distribuição 690 V / 480 V / 220 V e sistemas de UPS · Geração de energia em ambiente offshore: turbinas a gás aeroderivadas (LM2500, Rolls-Royce Avon), controle de velocidade, paralelismo e proteção de geradores · Motor de alta tensão (MT): 6,6 kV e 3,3 kV, aplicações em compressores de gás de produção, bombas de injeção de água e thruster de posicionamento dinâmico · Acionamentos de MT: topologias de inversor de média tensão — Neutral-Point Clamped (NPC), Cascaded H-Bridge (CHB), solução com transformador de tração — como cada topologia afeta o harmônico e a aplicação · Chaves de by-pass e diodos de roda livre em acionamentos MT: por que são críticos em ambientes onde a parada não é opção · Sistemas de posicionamento dinâmico (DP): como os sistemas elétricos sustentam o DP — thruster drives, qualidade de energia e confiabilidade elétrica · Qualificação de sistemas elétricos para ambiente marítimo: DNV GL, Lloyd''s Register e ABS — o que estas sociedades classificadoras exigem de equipamentos e instalações · Corrosão em instalações elétricas offshore: proteção de cabos e painéis em ambiente salino, cabos resistentes à UV e ao fogo (LSZH — Low Smoke Zero Halogen)','90–120 horas','["IEC 60092", "DNV GL Rules", "ABNT NBR 5419"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(31,74,'Iniciante · Perfil de entrada: Qualquer estudante de ensino médio técnico ou trabalhador industrial',1,'Compreende os quatro pilares da mecatrônica (mecânica, eletrônica, controle, computação) e como eles se integram em sistemas reais — domina os fundamentos de eletrônica analógica e digital essenciais para um técnico mecatrônico — programa microcontroladores em nível introdutório — interpreta diagramas elétricos e fluxogramas de controle','Mecatrônica: definição, história e campos de aplicação — por que a integração de disciplinas cria sistemas impossíveis de atingir com uma única área · Mecânica básica para mecatrônica: transmissão de movimento (engrenagens, correias, fusos de esferas), rigidez de estruturas e análise de cargas estáticas e dinâmicas em sistemas automatizados · Eletrônica analógica: amplificadores operacionais, filtros, conversores tensão-corrente (4-20 mA) e circuitos de condicionamento de sinal de sensores · Eletrônica digital: portas lógicas, flip-flops, contadores, registradores e conversores A/D e D/A — base para entender PLCs e microcontroladores · Microcontroladores e prototipação: Arduino e ESP32 como plataformas de aprendizado — programação básica em C/C++, I/O digital e analógico, comunicação serial, I²C e SPI · Sistemas de controle em malha aberta e fechada: conceito de realimentação (feedback), controlador PID — intuição física sem matemática pesada · Introdução à programação de CLPs: lógica ladder básica — contatos, bobinas, temporizadores e contadores · Sistemas embarcados em O&G: onde microcontroladores e FPGAs aparecem em instrumentos de fundo de poço, controladores de Christmas tree e sistemas de monitoramento embarcados','80–100 horas','["IEC 61131-3", "ISO 10218"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(32,75,'Iniciante · Perfil de entrada: B1 concluído ou equivalente em eletrônica básica',1,'Seleciona, instala, configura e diagnostica os principais sensores industriais (presença, posição, distância, visão básica) e atuadores (motores de passo, servomotores, válvulas solenoides) usados em sistemas de automação discreta — interpreta as especificações técnicas de sensores e sua integração com CLPs e sistemas de controle','Sensores de presença: indutivo, capacitivo, fotoelétrico (difuso, retro-reflexivo, barreira) e ultrassônico — princípio de funcionamento, campo de detecção, saída NPN/PNP e configuração · Sensores de posição: encoders incrementais e absolutos (resolução, PPR, comunicação SSI/BiSS), potenciômetros lineares e ângulo, LVDTs · Sensores de força e torque: células de carga, sensores piezoelétricos e strain gauges — condicionamento de sinal e amplificação · Sensores de temperatura em automação discreta: PT100, termopar, NTC/PTC — diferença de aplicação versus instrumentação de processo · Atuadores: motores de passo (bipolar/unipolar, microstepping, torque de retenção), servomotores (encoder de realimentação, drivers, controle de posição e velocidade) e atuadores lineares · Válvulas solenoides e proporcionais: funcionamento, especificação por pressão/vazão e interface com CLP · Comunicação de sensores com CLPs e controladores: IO-Link — o protocolo que está padronizando a comunicação ponto a ponto com sensores inteligentes · Diagnóstico de falhas em sensores: técnicas de inspeção, testes com multímetro e osciloscópio, interpretação de LEDs de status e comunicação de diagnóstico IO-Link','60–80 horas','["IEC 61131-9", "IEC 61131-2", "IEC 61076"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(33,76,'Pleno · Perfil de entrada: B1 + B2 concluídos',2,'Programa CLPs industriais em Ladder Diagram e Function Block Diagram para automação discreta de máquinas e linhas de produção — desenvolve e depura programas GRAFCET/SFC para controle sequencial — configura redes Profinet e EtherNet/IP — realiza manutenção corretiva em sistemas de automação com diagnóstico via software','IEC 61131-3: as 5 linguagens de programação de CLPs — Ladder (LD), Function Block Diagram (FBD), Structured Text (ST), Instruction List (IL) e Sequential Function Chart (SFC/GRAFCET) — quando usar cada uma · Siemens SIMATIC S7-1200/1500 com TIA Portal: o CLP mais utilizado na indústria de processo brasileiro — programação LD/FBD, blocos de dados, HMI KTP básico · Rockwell Allen-Bradley CompactLogix/ControlLogix com Studio 5000: referência da indústria americana e petroquímica — programação LD, motion control básico · Mitsubishi MELSEC e Omron NJ/NX: presença crescente na automação de máquinas — estrutura de programa e diferenças em relação a Siemens e Rockwell · CODESYS: o ambiente de programação IEC 61131-3 independente de fabricante — base da maioria dos CLP modernos, versão gratuita disponível · Redes industriais para CLPs: Profinet, EtherNet/IP, Modbus TCP — configuração de rede, I/O distribuído e diagnóstico de comunicação · Safety PLCs: diferença entre CLP padrão e CLP de segurança (certificação IEC 62061/ISO 13849) — quando é obrigatório · Aplicações em O&G: CLP em painéis de controle de válvulas on-off, sistemas de bloqueio (interlock), controle de máquinas de perfuração e sistemas de utilidades de plataformas','90–120 horas','["IEC 61131-3", "IEC 61784", "ISO 13849-1", "IEC 62061"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(34,77,'Pleno · Perfil de entrada: B1 concluído — noções de mecânica industrial',2,'Projeta e mantém circuitos pneumáticos para automação de máquinas — diagnostica e repara sistemas hidráulicos industriais — seleciona componentes (cilindros, válvulas, compressores, bombas hidráulicas) para aplicações industriais — integra sistemas pneumáticos e hidráulicos com controle elétrico via CLP','Pneumática industrial: ar comprimido como fonte de energia — produção, tratamento (filtro-regulador-lubrificador), distribuição e perdas de pressão · Atuadores pneumáticos: cilindros simples e dupla ação, cilindros rotativos, motor pneumático — cálculo de força, consumo de ar e seleção conforme carga · Válvulas pneumáticas: distribuição (2/2, 3/2, 4/2, 4/3, 5/2, 5/3), controle de fluxo (throttle valves) e válvulas proporcionais — aplicações de cada tipo · Circuitos pneumáticos com controle elétrico: integração de válvulas solenoides com CLPs, sensores de fim de curso, circuitos sequenciais · Normas de sinalização e diagramas pneumáticos: ISO 1219 — leitura e elaboração de diagramas · Aplicações críticas em O&G: atuadores pneumáticos em válvulas de controle e bloqueio de refinarias (spring-return para fail-safe), sistemas de atuação de árvores de natal, controle de chokes · Hidráulica industrial: óleo hidráulico como fluido de trabalho — propriedades, viscosidade e impacto no sistema · Componentes hidráulicos: bombas (engrenagem, palheta, pistão), cilindros, motores hidráulicos, válvulas de controle de direção, pressão e fluxo, acumuladores · Circuitos hidráulicos de alta potência: sistemas de mesas elevatórias, prensas, guindastes e mesas de perfuração — leitura de esquemas e diagnóstico de falhas · Servo-hidráulica e hidráulica proporcional: posicionamento de precisão com válvulas proporcionais — base dos sistemas de top drive e compensadores de movimento em plataformas','80–100 horas','["ISO 4413", "ISO 1219", "API 682", "ISO 4414"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(35,78,'Avançado · Perfil de entrada: C1 + B2 concluídos',3,'Programa robôs industriais de pelo menos um fabricante (KUKA, Fanuc ou ABB) em modo online e offline — realiza o comissionamento básico de uma célula robótica — compreende os fundamentos de cinemática de robôs (espaço de juntas, espaço cartesiano, posicionamento e orientação) — programa robôs colaborativos (cobots) com ensino por guiamento manual — integra robôs com CLPs via I/O e protocolo industrial','Fundamentos de robótica industrial: topologias de robôs (articulado 6-eixos, SCARA, delta, paralelo, colaborativo), espaço de trabalho, repetibilidade, payload e alcance — como escolher o robô certo · Cinemática direta e inversa: transformações homogêneas, frames cartesianos, Tool Center Point (TCP) e Base Frame — sem álgebra linear pesada, com foco na aplicação prática · Programação de KUKA (KRL): programa básico em KRL (KUKA Robot Language) — movimento linear, articular e circular — condicionamento de E/S — subprogramas · Programação de Fanuc (TP e Karel): teach pendant programming, motion instructions, I/O signals, register operations · Programação de ABB (RAPID): estrutura do programa RAPID, módulos, rotinas, instruções de movimento e tratamento de eventos · Robôs colaborativos — Universal Robots (URScript): programação via PolyScope (interface gráfica), force torque sensing, safety configuration · Simulação offline de robôs: RoboDK (versão gratuita), KUKA Sim, ABB RobotStudio — criação de células virtuais, validação de trajetória e análise de colisão · Aplicações em O&G e indústria pesada: inspeção robotizada de tanques e dutos (robôs de escalada magnética), soldagem automatizada em estaleiros, manuseio de cargas pesadas em áreas perigosas, pintura de estruturas offshore','100–130 horas','["ISO 10218-2", "IEC 62061", "ISO 10218-1"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(36,79,'Avançado · Perfil de entrada: B2 + C1 concluídos',3,'Configura sistemas de visão de máquina para inspeção dimensional e detecção de defeitos em processos industriais — seleciona câmeras, iluminação e lentes para diferentes aplicações de inspeção — programação básica de sistemas de visão (Cognex In-Sight, Keyence IV) — integra sistemas de visão com CLPs e robôs — compreende os princípios estatísticos básicos de controle de qualidade (CEP — Controle Estatístico de Processo)','Fundamentos de visão de máquina: processamento de imagem digital (pixel, resolução, escala de cinza, binarização, morfologia), câmera CCD/CMOS e sensor de linha · Iluminação industrial: tipos (bright field, dark field, backlight, coaxial), cores, anéis de LED — como a iluminação determina 70% do sucesso de uma aplicação de visão · Óptica para visão industrial: relação objeto-imagem, distância focal, profundidade de campo, lentes telecêntricas · Cognex In-Sight: programação de aplicações de inspeção com EasyBuilder — presença/ausência, medição dimensional, leitura de código de barras e QR, verificação de caracteres (OCR) · Keyence IV/CV Series: configuração de inspeção com interface gráfica, integração com CLP via I/O e Ethernet · Câmeras 3D e perfilometria laser: princípio de triangulação, aplicações em inspeção de solda, corte e perfilagem de superfície · Controle Estatístico de Processo (CEP) básico: cartasde controle X-R e X-S, Cp e Cpk, detecção de causas especiais — como dados de visão alimentam sistemas de CEP · Aplicações industriais críticas: inspeção de cordão de solda em tempo real (integrada a robôs de solda), verificação de integridade de revestimentos, medição dimensional de peças usinadas · Aplicações em O&G: inspeção de juntas soldadas em dutos, verificação de assentamento de conexões, inspeção de corrosão superficial por câmeras robotizadas','80–100 horas','["ISO 5725", "IEC 13273", "ISO 9001"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(37,80,'Avançado · Perfil de entrada: B1 + C1 concluídos — noções de desenho técnico mecânico',3,'Programa operações de usinagem em linguagem G-Code e via software CAM — opera e mantém máquinas CNC (torno, fresa, centro de usinagem) — cria e modifica modelos 3D para aplicações de manufatura — gera caminhos de ferramenta e simula usinagem antes de executar na máquina — compreende os parâmetros de corte e sua influência na qualidade e na vida da ferramenta','Fundamentos de usinagem: processos de corte (torneamento, fresamento, furação, retificação), materiais de ferramenta (HSS, metal duro, cerâmica, CBN, diamante) e geometria de corte · Parâmetros de corte: velocidade de corte, avanço, profundidade de corte — interação com material, ferramenta e acabamento superficial · G-Code e linguagem de programação CNC: estrutura de um programa CNC (blocos, palavras, endereços), ciclos fixos (G81-G89), compensação de ferramenta (G41/G42), subprogramas · Sistemas CNC: Fanuc (a referência mundial), Siemens Sinumerik, Heidenhain — diferenças de interface e programação · Software CAD: Autodesk Fusion 360 (gratuito para estudantes e pequenos fabricantes) — modelagem 3D paramétrica, montagens e desenho técnico · Software CAM: Fusion 360 CAM — criação de operações de usinagem, seleção de estratégia de caminho de ferramenta, simulação e geração de G-Code · Manufatura aditiva (impressão 3D): FDM, SLA e SLS — quando usar manufatura aditiva versus subtrativa, aplicações em O&G (prototipagem rápida de peças de reposição) · Metrologia dimensional para usinagem: paquímetro, micrômetro, relógio comparador, rugosímetro e MMC (Máquina de Medir por Coordenadas) — uso correto e tolerâncias geométricas (GD&T/GPS) · Aplicações em O&G e estaleiros: fabricação de peças de reposição offshore, usinagem de flanges e conexões de alta pressão, reparo de árvores de natal e equipamentos de fundo de poço','90–120 horas','["ISO 6983", "ABNT NBR 6158", "ISO 1101", "ISO 10303"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(38,81,'Avançado · Perfil de entrada: C1 + B2 concluídos — noções básicas de redes (IP, TCP/UDP)',3,'Compreende a arquitetura de sistemas de manufatura digital (ISA-95) — configura comunicação OPC UA entre equipamentos e sistemas supervisórios — entende o papel de Edge Computing e Cloud na coleta e processamento de dados industriais — tem visão funcional de sistemas MES e como eles se integram com chão de fábrica e ERP','Indústria 4.0: os 9 pilares tecnológicos — IoT Industrial, Big Data, simulação, robótica autônoma, fabricação aditiva, realidade aumentada, cloud computing, cibersegurança industrial e integração horizontal/vertical · Modelo ISA-95 (IEC 62264): pirâmide de automação modernizada — ERP (Nível 4), MES (Nível 3), SCADA (Nível 2), CLP (Nível 1), campo (Nível 0) · OPC UA (IEC 62541): o protocolo universal de comunicação industrial para I4.0 — modelo de informação, servidor/cliente, publicação/assinatura, segurança e semântica · Edge Computing industrial: coletores de dados de chão de fábrica (Siemens IOT2040, Raspberry Pi com Node-RED, MQTT) — processamento local versus envio para nuvem · MES (Manufacturing Execution Systems): o que um MES faz — OEE (Overall Equipment Effectiveness), rastreabilidade, gestãode ordens de produção, controle de qualidade e genealogia de produto · Integração MES-ERP-SCADA: como dados de chão de fábrica chegam ao SAP ou Oracle — connectors, APIs REST e interfaces de integração · Segurança em redes industriais I4.0: zona desmilitarizada (DMZ) industrial, segmentação IT/OT e IEC 62443 resumido para o técnico de automação · Aplicações em O&G e processo contínuo: coleta de dados de CLPs e instrumentos de campo via OPC UA, dashboards de eficiência de planta, integração com sistemas de gestãode manutenção (SAP PM) via MES','80–100 horas','["ISO 22400", "ISA-95", "IEC 62264", "IEC 62443", "IEC 62541"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(39,82,'Avançado · Perfil de entrada: C1 + I1 concluídos — noções de modelagem CAD (Fusion 360 ou equivalente)',3,'Compreende o conceito e os diferentes níveis de fidelidade de um gêmeo digital — cria modelos de simulação de sistemas mecatrônicos simples (modelagem de motor + inversor, modelagem de circuito pneumático) — usa plataformas de gêmeos digitais para monitoramento e otimização de desempenho de máquinas — conecta dados de sensores reais a modelos de simulação','Gêmeo digital: definição e os quatro níveis de maturidade — Digital Shadow (coleta passiva), Digital Twin (bidirecional), Predictive Twin (previsão) e Autonomous Twin (autogestão) · Modelagem e simulação de sistemas mecatrônicos: modelagem física de motores, transmissões, cilindros pneumáticos e circuitos de controle com Simulink ou Modelica · Plataformas de simulação gratuitas ou open source: OpenModelica (Modelica), MATLAB Online (limited free), Simscape (paid) — como usar OpenModelica para simular sistemas mecânicos e elétricos integrados · FESTO FluidSIM: simulação de circuitos pneumáticos, hidráulicos e eletropneumáticos — ferramenta de referência no ensino técnico · Gêmeos digitais para manutenção preditiva: como conectar dados de sensores (vibração, temperatura, corrente) a modelos de degradação para prever falhas · Plataformas industriais: Siemens Simcenter, PTC ThingWorx, GE Predix, ANSYS Digital Twin — o que cada um oferece gratuitamente · Realidade aumentada (AR) em manutenção: Microsoft HoloLens, Vuforia (PTC) e AR industrial — como a AR suporta o técnico mecatrônico na manutenção de sistemas complexos · Aplicações em O&G: gêmeo digital de compressor de gás (modelo de desempenho versus dados reais de vibração e eficiência), simulação de sistema de bombeamento multifásico, AR para guia de manutenção de BOP','80–100 horas','["IEC 61131-3", "IEC 62832"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(40,86,'Iniciante · Perfil de entrada: Qualquer estudante de ensino médio ou trabalhador industrial',1,'Compreende as principais fontes de energia renovável e seus princípios físicos — conhece os recursos naturais do Brasil para solar, eólico, hidráulico e biomassa — entende o sistema elétrico brasileiro (SIN) e como as renováveis se integram à rede — analisa o Atlas Solarimétrico e o Atlas Eólico do Brasil para avaliar potencial de projetos','Fontes renováveis: solar (fotovoltaico e termossolar), eólico (onshore e offshore), hidráulico (UHE, PCH, CGH), biomassa, geotérmica e maremotriz — princípios físicos e aplicações de cada uma · Recurso solar no Brasil: irradiação global horizontal (GHI), irradiância direta normal (DNI) e difusa — como ler mapas de irradiação e o que eles significam para projetos · Recurso eólico no Brasil: ventos alísios do Nordeste, perfil de vento com altura, fator de capacidade e o por quê de o Brasil ter os ventos mais estáveis do mundo · Sistema Interligado Nacional (SIN): como funciona a rede elétrica brasileira, ANEEL, ONS, CCEE e o papel das renováveis na matriz elétrica · RENOVABIO e biocombustíveis no Brasil: política de descarbonização do setor de transporte, CBIO e metas · Lei 14.300/2022 (marco legal da micro e minigeração distribuída): o que mudou para quem instala e para quem opera FV · Tendências de mercado: crescimento do setor renovável brasileiro em números — empregos criados, capacidade instalada e perspectivas até 2030','50–70 horas','[]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(41,87,'Pleno · Perfil de entrada: F1 concluído + noções de eletricidade (equivalente E1 do Atlas Eletrotécnica)',2,'Dimensiona sistemas FV on-grid e off-grid para aplicações residenciais, comerciais e industriais — elabora projetos conforme ABNT NBR 16690 e requisitos da concessionária — instala módulos, inversores, estruturas e proteções — comissiona o sistema e realiza os ensaios iniciais de desempenho — emite o formulário de acesso à rede (ANEEL)','Célula fotovoltaica: efeito fotovoltaico, tipos de célula (monocristalina, policristalina, thin film, bifacial, HJT, TOPCon) — eficiência, características e tendências · Módulo fotovoltaico: curva IV, potência de pico (Wp), temperatura de operação nominal (TONC), coeficientes de temperatura — como a temperatura afeta a produção · Inversor solar: on-grid (grid-tie), off-grid (com bateria) e híbrido — topologias, eficiência do inversor (europeia e CEC), MPP tracking · Dimensionamento de sistemas FV: cálculo de consumo, dimensionamento de módulos e inversores, análise de sombreamento (SunEye, Sketchup, PVsyst), análise de viabilidade econômica (TIR, VPL, payback) · Cabeamento e proteções: seção de cabos CC e CA, DPS (dispositivo de proteção contra surto), disjuntores, string boxes e aterramento · Instalação de estruturas: telhado cerâmico, metálico, fibrocimento, flat roof e solo — fixação correta, vão máximo e carga estrutural · Comissionamento: ensaio de isolamento, medição de tensão em circuito aberto (Voc) e corrente de curto-circuito (Isc) de string, termografia inicial e verificação de comunicação · Normas brasileiras: ABNT NBR 16690 (projeto e instalação), NBR 16274 (geração distribuída), NBR 5410 e NBR 14039 aplicadas ao FV','90–120 horas','["ABNT NBR 5410", "IEC 62548", "IEC 61215", "ABNT NBR 16690", "ABNT NBR 16612", "IEC 62109", "ABNT NBR 16274"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(42,88,'Avançado · Perfil de entrada: S1 concluído',3,'Opera e mantém sistemas FV de médio e grande porte (parques utility-scale) — realiza diagnóstico avançado com curva IV, termografia infravermelha e eletroluminescência (EL imaging) — monitora desempenho via SCADA e identifica desvios de PR (Performance Ratio) — conduz inspeção de drone com análise de imagem térmica — elabora relatórios de O&M e gestãode contratos de serviço','Indicadores de desempenho FV: PR (Performance Ratio), YF (Yield Final), YR (Yield de Referência), CUF (Capacity Utilization Factor) — como calculá-los e interpretá-los · Monitoramento e SCADA para sistemas FV: estrutura de dados, alertas, detecção automática de falhas e relatórios de disponibilidade · Análise de curva IV: ensaiador portátil de curva IV, desvios de Voc, Isc, Vmp, Imp e Pmp — o que cada desvio indica sobre o módulo · Termografia infravermelha em módulos FV: células em ponto quente (hot cell), bypass diode shunting, soiling diferencial — norma IEC 62446-3 · Eletroluminescência (EL imaging): funcionamento, padrões de defeito (trincas, descolamento de célula, inactive cells) e quando usar · Inspeção com drones: planejamento de missão, câmera térmica embarcada, processamento de ortofoto e identificação de módulos degradados em parques utility-scale · Limpeza e anti-soiling: impacto do sombreamento por sujeira no Brasil (especialmente no Nordeste), frequência de limpeza, custo versus ganho e soluções robotizadas · Substituição de inversores e diagnóstico de falha: análise de log de falhas, substituição de componentes internos, curva de eficiência pós-reparo','80–100 horas','["IEC 62446-1", "IEC 61724", "ABNT NBR 16274", "IEC 62446-3"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(43,89,'Pleno · Perfil de entrada: F1 concluído + noções de eletromecânica (equivalente M1 do Atlas Eletrotécnica ou Atlas Mecatrônica)',2,'Compreende o funcionamento completo de uma turbina eólica de eixo horizontal (HAWT) — realiza manutenção preventiva e corretiva de nível 1 e 2 em aerogeradores onshore — opera sistemas SCADA de parques eólicos — realiza trabalho em altura conforme NR-35 em torres eólicas — identifica e diagnostica as falhas mais comuns em aerogeradores','Conversão de energia eólica: lei de Betz, curva de potência da turbina, fator de capacidade e densidade de potência do vento · Arquitetura da turbina eólica: rotor (pás, cubo, pitch control), nacelle (caixa de multiplicação, gerador, transformador), torre (tubular de aço, torre treliçada, torre de concreto) e fundação (gravidade, monopilares, jacket) · Sistemas internos da nacelle: sistema de yaw (orientação do rotor), sistema de pitch (regulagem de ângulo das pás), sistema de freio (mecânico e aerodinâmico), sistema de refrigeração e sistema elétrico de geração · Aerogeradores modernos: turbinas de velocidade variável com conversor de frequência total (full converter), controle MPPT, integração com rede · Operação e manutenção (O&M) onshore: manutenção preventiva (PM1, PM2, PM3), principais componentes com maior taxa de falha (rolamentos do gerador, caixa multiplicadora, pitch actuator) · SCADA para eólica: estrutura de dados, alarmes, KPIs de disponibilidade (OEE, AEP) e relatórios de produção · Trabalho em altura em torres eólicas: especificidades além da NR-35 padrão — sistema de içamento, LOTO em turbinas, espaços confinados da nacelle · ABEEólica: regulamentação brasileira de eólica, boas práticas do setor e capacitação','80–100 horas','["IEC 61400-12-1", "NR-35", "DNV standards ", "IEC 61400", "ABNT NBR 16622"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(44,90,'Avançado · Perfil de entrada: W1 + NR-33 básico (equivalente N2 do Atlas Segurança) — HUET (desejável)',1,'Domina as especificidades técnicas e de segurança de turbinas offshore — é candidato qualificado para certificação GWO BST/BSTR — compreende os diferentes tipos de fundação offshore (monopilares, jacket, flutuantes) — opera e mantém aerogeradores offshore conforme padrões internacionais — entende a cadeia completa de instalação e O&M de parques eólicos offshore','Eólica offshore versus onshore: os quatro grandes desafios adicionais — ambiente marítimo corrosivo, acesso por barco ou helicóptero, complexidade de fundação submarina e custo de O&M elevado · Fundações offshore: monopilares (até 45m de lâmina d''água), jacket e tripod (45–80m), gravidade (solos específicos), fundações flutuantes (Spar, Semi-sub, TLP — para águas ultraprofundas) · Turbinas offshore modernas: turbinas de 12–20 MW, rotores de 220–280m de diâmetro, estruturas de aço e materiais especiais para ambiente marítimo · Sistemas de transmissão offshore: cabos submarinos de AT, plataformas offshore de transformação (HVDC para parques distantes), interface com a rede terrestre · Certificação GWO (Global Wind Organisation): estrutura do programa — BST (Basic Safety Training) e BSTR (Basic Technical Training) — o que cada módulo exige · Sobrevivência no mar para técnico eólico: HUET (Helicopter Underwater Escape Training), equipamentos de salvatagem SOLAS, abandono de turbina em emergência marítima · O&M offshore: estratégias de manutenção (corrective, preventive, predictive), janelas meteorológicas de acesso, CTV (Crew Transfer Vessel) e OSV (Offshore Support Vessel) · Mercado offshore brasileiro: potencial de 700+ GW no Nordeste, projetos licenciados, parceria SENAI-RN/FAETI e OEP, cronograma de primeiras instalações','90–120 horas','["DNV GL ST", "NR-33", "IEC 61400-3"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(45,91,'Avançado · Perfil de entrada: F1 + noções de química básica e eletricidade',3,'Compreende as principais rotas de produção de hidrogênio (grey, blue, green) — entende o funcionamento e os principais parâmetros de eletrolisadores alcalinos, PEM e SOEC — conhece os requisitos de segurança para instalações de H₂ — compreende a cadeia Power-to-X (H₂ → amônia verde, metanol verde, SAF) — analisa a viabilidade econômica básica de projetos de H₂V','Cores do hidrogênio: grey (SMR sem CCS), blue (SMR + CCS), green (eletrólise com renovável), pink (nuclear), turquoise (pirólise de metano) — por que as "cores" importam para certificação e mercado · Eletrólise da água: reação eletroquímica, eficiência de Faraday, consumo específico de energia (kWh/kg H₂) e as três tecnologias comerciais · Eletrolisadores alcalinos: maturidade tecnológica, faixa de operação (20–30 bar), vantagens de custo, limitações de carga parcial e tempo de resposta · Eletrolisadores PEM: alta flexibilidade de carga (responde a variações do vento/solar em segundos), maior pureza do H₂, maior custo de BoP · Eletrolisadores SOEC: alta eficiência a alta temperatura, sinergia com calor de processo industrial — tecnologia emergente · Segurança em instalações de H₂: propriedades físico-químicas (densidade, LEL, UEL, temperatura de autoignição, IDLH), Jet Fire, Flash Fire e BLEVE — diferenças em relação a hidrocarbonetos · Detecção e instrumentação para H₂: sensores catalíticos (fio de platina), sensores TC (condutividade térmica), sensores eletroquímicos — limitações de cada tecnologia · Power-to-X: H₂ → amônia verde (Haber-Bosch + H₂V), metanol verde (CO₂ + H₂V via rWGS), SAF (Sustainable Aviation Fuel via Fischer-Tropsch), metano sintético (Power-to-Gas) · Mercado de H₂V no Brasil: Pecém (CE), Porto de Açu (RJ), Suape (PE) — projetos anunciados, investimentos e cronograma','90–120 horas','["ABNT NBR 15526", "ISO 22734", "NFPA 2", "IEC 62282"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(46,92,'Avançado · Perfil de entrada: F1 + noções de química industrial ou de processos',3,'Compreende as principais tecnologias de captura de CO₂ (pós-combustão, pré-combustão, oxycombustion) e seus campos de aplicação — entende os fundamentos do transporte e armazenamento geológico de CO₂ — conhece os projetos de referência global e o caso específico do pré-sal brasileiro — analisa o impacto de CCUS nas perspectivas de carreira em O&G','Por que CCUS importa para O&G: o setor de petróleo e gás é responsável por ~15% das emissões globais diretas — e é também quem tem a infraestrutura e expertise para armazenar CO₂ em larga escala · Tecnologias de captura pós-combustão: absorção química com aminas (MEA, MDEA), adsorção por pressão (PSA), membranas de separação — vantagens, desvantagens e custos por tecnologia · Captura pré-combustão: reformação do gás natural com shift e separação H₂/CO₂ — base do blue hydrogen · Oxycombustion: queima em atmosfera de O₂ puro para obter CO₂ concentrado — aplicação em plantas de gás natural · Transporte de CO₂: pipeline supercrítico (acima de 31°C e 73 bar) versus transporte líquido — especificidades de segurança e corrosão · Armazenamento geológico: aquíferos salinos profundos, campos de petróleo/gás depletados (EOR-CCS) e minas de carvão · O caso do pré-sal brasileiro: CO₂ produzido junto com o petróleo (até 12%), separação por membranas e reinjeção — a maior operação de CCUS-EOR do mundo · Projetos de referência: Sleipner (Noruega, desde 1996), Quest (Canadá), Boundary Dam (Canadá), Northern Lights (Noruega), Illinois Industrial CCS · Monitoramento de armazenamento: técnicas sísmicas 4D, geoquímica de fluidos, pressão em poços de observação','70–90 horas','["ISO 27914", "IEC 62073"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(47,93,'Avançado · Perfil de entrada: S1 + W1 concluídos + noções de elétrica (equivalente E1 Atlas Eletrotécnica)',3,'Compreende as tecnologias de armazenamento estacionário de energia (BESS) — dimensiona sistemas de armazenamento para aplicações de FV+BESS e eólica+BESS — entende o funcionamento de smart grids e microrredes — conhece os requisitos regulatórios brasileiros para armazenamento e geração distribuída avançada','Tecnologias de armazenamento estacionário: baterias de lítio (LFP, NMC, NCA), flow batteries (vanádio, zinco-bromo), armazenamento por ar comprimido (CAES), volante de inércia, armazenamento hidráulico por bombeamento (PSH) — aplicações, custos e maturidade tecnológica · BESS (Battery Energy Storage System): arquitetura de sistema (módulos, BMS, PCS, transformador, proteções), serviços de mercado (peak shaving, frequency regulation, arbitragem, firm capacity) · Dimensionamento de BESS: capacidade (MWh), potência (MW), C-rate, ciclos de vida, degradação de capacidade e análise de viabilidade econômica · Smart grid: conceito, pilares tecnológicos (AMI, DERMS, EMS, GIS), redes de comunicação (PLC, RF mesh, Fiber) e o papel da demanda flexível · Microrredes (microgrids): definição, modos de operação (grid-connected, islanded), controle de frequência e tensão em ilha, casos de uso em instalações industriais remotas e offshore · Regulamentação brasileira: Resolução ANEEL sobre armazenamento de energia, tratamento de BESS no marco da GD (Lei 14.300/2022), projetos-piloto ONS · Projetos referenciais: BESS de Porto Rico pós-furacão, Tesla Hornsdale (Australia), Projeto Leste da Comerc Energia, sistemas FV+BESS em comunidades isoladas do Brasil','70–90 horas','["IEC 62933", "ABNT NBR 16690", "IEC 62619"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(48,94,'Avançado · Perfil de entrada: F1 concluído — interesse em gestão e sustentabilidade',3,'Compreende a estrutura dos mercados de carbono voluntário e regulado — aplica os protocolos de inventário de GEE (GHG Protocol, ISO 14064) — apoia a elaboração de relatórios de sustentabilidade conforme GRI e TCFD — conhece as metodologias de projetos de carbono (VCS, Gold Standard) — entende o CBIO e o RENOVABIO no contexto brasileiro','Gases de efeito estufa: composição do GWP (Global Warming Potential), CO₂ equivalente, escopos 1, 2 e 3 de emissões — por que o Escopo 3 é o mais difícil e o mais importante · GHG Protocol: a metodologia global de inventário de emissões mais utilizada — como aplicar Escopo 1, 2 e 3, ferramentas de cálculo gratuitas · ISO 14064: o padrão internacional para inventários de GEE, verificação de terceira parte e declarações organizacionais · Mercado de carbono voluntário: como funciona, projetos creditados (REDD+, eficiência energética, energia renovável), VERRA VCS e Gold Standard — processo de validação e verificação · Mercado regulado brasileiro: CBIO (Crédito de Descarbonização do RenovaBio), Sistema Brasileiro de Comércio de Emissões (SBCE — em implementação), B3 e negociação de créditos · Relatórios de sustentabilidade: GRI (Global Reporting Initiative) — estrutura e principais indicadores — TCFD (Task Force on Climate-related Financial Disclosures) — por que bancos e investidores exigem — CDP (Carbon Disclosure Project) · ESG na prática industrial: implementação de métricas ESG em operações de O&G e renováveis, avaliação de risco climático físico e de transição · Taxonomia verde: critérios europeus (EU Taxonomy) e brasileira (Taxonomia Sustentável Brasileira — em construção)','70–90 horas','["ISO 14064", "ISO 14064-1"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(49,98,'Iniciante · Perfil de entrada: Qualquer estudante de curso técnico em automação, eletrotécnica ou mecatrônica',1,'Domina os fundamentos de eletrônica analógica e digital essenciais para a automação industrial — projeta e analisa circuitos de condicionamento de sinal — programa microcontroladores e FPGAs em nível introdutório — interpreta esquemas eletrônicos de equipamentos industriais e realiza manutenção de placas e módulos eletrônicos','Eletrônica analógica para automação: amplificadores operacionais (AO) em configurações de instrumentação (ganho, CMRR, impedância de entrada), filtros ativos (passa-baixa, passa-alta, passa-banda) para condicionamento de sinal de sensores · Conversores A/D e D/A: resolução, taxa de amostragem, erros de quantização — como a conversão analógico-digital afeta a precisão de uma medição industrial · Eletrônica digital: lógica combinacional e sequencial, máquinas de estado, memórias (EEPROM, Flash) e interfaces de comunicação (SPI, I²C, UART) · Microcontroladores industriais: arquitetura de microcontroladores de 32 bits (ARM Cortex-M, ESP32), periféricos de entrada analógica (ADC multicanal), saídas PWM e comunicação serial — base dos transmissores inteligentes modernos · Eletrônica de potência introdutória: transistores de comutação (BJT, MOSFET, IGBT), drivers de gate e circuitos de proteção — base para entender os inversores de frequência que controlam motores · Instrumentação eletrônica: ponte de Wheatstone, amplificador de instrumentação (INA), células de carga e transdutores piezorresistivos — como funciona internamente um transmissor de pressão · Osciloscópio digital (DSO): medição de forma de onda, análise de protocolo serial (UART, SPI, I²C), análise de ripple de fontes de alimentação','70–90 horas','["IEC 60068", "IEC 61000-4"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(50,99,'Pleno · Perfil de entrada: E1 concluído',2,'Analisa e mantém circuitos de condicionamento de sinal de campo (4–20 mA, 0–10 V, frequência de pulso) — dimensiona fontes de alimentação industriais redundantes (24 VCC e 230 VCA) — entende o funcionamento interno de conversores de potência usados em inversores e soft starters — realiza diagnóstico e reparo de módulos de I/O de CLPs e DCS','Padrão 4–20 mA: por que dois fios, por que corrente (não tensão) — o padrão que conecta 90% dos instrumentos industriais ao sistema de controle · Transmissores com laço de 2 fios: alimentação pelo laço (loop-powered), resistor de precisão, conversão corrente-tensão e interface com módulos de AI de CLP/DCS · Fontes de alimentação industriais: topologias (linear versus chaveada), eficiência, ondulação de saída e redundância de fontes (diodo de ORing, módulos redundantes) — por que falha de fonte derruba a planta inteira · Barreiras de segurança intrínseca (Zener barriers) e isoladores galvânicos: função, especificação e instalação em áreas classificadas ATEX · SMPS (Switch-Mode Power Supply): topologias de conversores (buck, boost, flyback, full-bridge) — funcionamento e diagnóstico de falhas · Conversores de sinal de campo: isoladores 4–20 mA, conversores de frequência-corrente, pontes de potenciômetro e condicionadores de RTD/termopar · Manutenção de módulos de I/O de DCS/CLP: diagnóstico com multímetro e osciloscópio, substituição de módulo, configuração de jumpers e endereçamento · Qualidade de alimentação em automação: efeitos de ruído, terra de referência, aterramento de shield de cabo de instrumento e separação de malhas de terra','60–80 horas','["ABNT NBR 5410", "IEC 60947-1", "IEC 60079-11"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(51,100,'Pleno · Perfil de entrada: E1 concluído + noções de instrumentação básica (transmissores, válvulas on-off)',2,'Programa CLPs industriais para controle de processos contínuos (não apenas máquinas) — configura malhas de controle PID em CLP — integra entradas analógicas de transmissores 4–20 mA e saídas analógicas para válvulas de controle — configura comunicação Modbus RTU/TCP com instrumentos de campo — realiza diagnóstico e manutenção de CLPs em ambiente de processo','Arquitetura de CLP para processo: módulos AI (4–20 mA, RTD, termopar), AO (4–20 mA, posicionador), DI (24 VCC, NAMUR Ex ia) e DO (relé, transistor, TRIAC) — como selecionar módulo certo para cada tipo de sinal de campo · Endereçamento e configuração de módulos analógicos: resolução (12, 14, 16 bits), faixa de entrada, detecção de fio aberto/curto, diagnóstico de canal · Controle PID em CLP: blocos PID na linguagem Function Block Diagram (FBD), parâmetros Kp/Ti/Td, auto-tuning, controle feedforward, controle em cascata, anti-windup · Modos de controle: automático, manual, CAS (cascata) — transição sem bump (bumpless transfer) e como implementar em IEC 61131-3 · Modbus RTU e TCP/IP: protocolo de comunicação onipresente em instrumentos industriais — leitura de registradores, escrita de setpoints, diagnóstico de comunicação · Comunicação com DCS: quando usar CLP standalone versus CLP integrado ao DCS como Remote I/O — critérios de decisão · Redundância de CLP: topologias 1oo2, 2oo3 e hot standby — por que são obrigatórias em sistemas de intertravamento e como se diferenciam do CLP padrão · Diagnóstico de CLP em campo: leitura de LED de status, interpretação de log de erros, substituição de módulo em linha com restrição de parada','80–100 horas','["ISA 5.1", "IEC 61131-3", "ISA 88", "ISA 106"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(52,101,'Pleno · Perfil de entrada: A1 concluído',2,'Configura e mantém sistemas SCADA industriais para plantas de processo — cria telas de operação de processo (mimic screens) conforme boas práticas de design (ISA 101) — configura gerenciamento de alarmes conforme ISA 18.2 — conecta SCADA a CLPs e DCS via OPC UA/DA — gera relatórios de processo e tendências históricas','Arquitetura de sistemas SCADA industriais: servidor SCADA, clientes de operação, historian de processo, interface com ERP e MES — e como cada componente se relaciona · Plataformas líderes de mercado: AVEVA System Platform (ex-Wonderware InTouch) e Ignition (Inductive Automation) — as plataformas mais usadas em refinarias e plantas de processo no Brasil · Configuração de tags e banco de dados de processo: tipos de tag (analógico, discreto, string, evento), endereçamento OPC, alarmação e histórico · Design de telas de operação de processo (SCADA): boas práticas de HCD (Human-Centered Design) conforme ISA 101 — hierarquia de telas, filosofia de cor, informação em destaque versus informação de contexto · Gerenciamento de alarmes: ISA 18.2 — filosofia de alarmes, priorização, supressão, alarmes nuisance e procedimentos de normalização · OPC DA (clássico) e OPC UA: configuração de servidor OPC, leitura de tags de CLPs Siemens, Rockwell e outros — protocolo universal de comunicação de dados de processo · Historian de processo: configuração de gravação por exceção e por tempo, compressão de dados (Swinging Door), consulta histórica e relatórios de performance · Segurança de acesso a SCADA: gestãode usuários, níveis de permissão, auditoria de alterações — compliance com normas industriais e IEC 62443','80–100 horas','["ISA 18.2", "ISA 101", "IEC 62541", "IEC 27001"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(53,102,'Pleno · Perfil de entrada: E1 + A1 concluídos',2,'Instala, configura, calibra e mantém os principais instrumentos industriais (transmissores de pressão, temperatura, nível e vazão — válvulas de controle) — interpreta e elabora diagramas de instrumentação (P&ID) — realiza calibração em campo e emite certificados de calibração — diagnostica falhas em malhas de controle do campo ao sistema','P&ID (Piping and Instrumentation Diagram): leitura e interpretação completa conforme ISA 5.1 — símbolos de instrumentos, linhas de processo e de instrumento, identificação de tags, válvulas e controladores · Transmissores de pressão: princípio de medição piezorresistivo e capacitivo, zero e span, supressão e elevação de zero, manifolds de 3 e 5 vias, instalação em processo · Transmissores de temperatura: termopar (tipos J, K, S, R, E, T), RTD (PT100/PT1000 — 2, 3 e 4 fios) e transmissores de temperatura com HART — fontes de erro, seleção e instalação · Medição de vazão: princípios de medição (diferencial de pressão — placa de orifício, tubo de Pitot — magnético — vórtice — Coriolis — ultrassônico) — aplicações de cada princípio, limitações e manutenção · Medição de nível: pressão hidrostática (borbulhador, selagem capilar), ultrassônico, radar, guia de ondas (guided wave radar) — seleção por aplicação e configuração · Válvulas de controle: tipos (globo, borboleta, esfera, cage, ângulo), tamanho (Cv), atuador pneumático, posicionador (analógico e HART), características de fluxo · Calibração industrial: procedimento de calibração de transmissores, traçabilidade metrológica a padrões RBC/INMETRO, ajuste de zero e span, emissão de certificado de calibração · Diagnóstico de malhas de controle: análise de sinal 4–20 mA com clamp meter, medição de resposta ao degrau, identificação de válvula travada (stiction), transmissor com deriva','90–120 horas','["ABNT NBR 14518", "IEC 60770", "IEC 17025", "IEC 61511", "ISA 5.1"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(54,103,'Avançado · Perfil de entrada: I1 concluído',3,'Configura, diagnostica e mantém instrumentos com comunicação HART (universal) e redes de campo PROFIBUS PA e Foundation Fieldbus — usa HART communicator portátil e ferramentas de diagnóstico de rede de campo — entende a integração desses protocolos com DCS — conhece a evolução para Ethernet-APL (Advanced Physical Layer) — o futuro das redes de campo','HART (Highway Addressable Remote Transducer): protocolo FSK sobreposto ao sinal 4–20 mA, variáveis primária/secundária/terciária/quaternária (PV, SV, TV, QV), Device Description (DD), modo multidrop (até 15 dispositivos, mínima corrente) · HART communicator portátil: identificação do dispositivo, leitura de variáveis de processo, configuração de parâmetros, diagnóstico de falha de transmissor, trim de zero e span pelo loop · WirelessHART (IEC 62591): malha em mesh de 2,4 GHz, latência de 1 segundo, alimentação por bateria — aplicações em pontos sem infraestrutura de cabo, instrumentação em locais perigosos · PROFIBUS PA: camada física MBP (Manchester Bus Powered), topologia barramento/estrela/árvore, alimentador de segmentos (PA segment coupler), diagnóstico de rede com PROFIBUS tester · Foundation Fieldbus (FF H1): camada física similar ao PA, tecnologia mais antiga e presente em refinarias e plantas petroquímicas brasileiras, bloco de função dentro do transmissor, controle no campo (field control) · Ethernet-APL (Advanced Physical Layer): o sucessor de HART/PA/FF sobre Ethernet industrial a 2 fios, alimentação pelo cabo, 10 Mbit/s — a revolução da instrumentação digital que chegará às plantas nos próximos anos · FieldComm Group: a organização que mantém HART, Foundation Fieldbus, WirelessHART e Ethernet-APL — documentação técnica gratuita · EDDL e FDI (Field Device Integration): Device Description Library, Field Device Tool (FDT/DTM), integração de instrumentos no DCS — com','80–100 horas','["IEC 61784-5-3", "IEC 62591", "IEC 61158", "IEC 62769"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(55,104,'Avançado · Perfil de entrada: A1 + A2 concluídos + noções básicas de redes TCP/IP',3,'Configura redes industriais para plantas de processo (PROFINET, EtherNet/IP, Modbus TCP) — implementa servidores OPC UA para integração de dados de PLCs e DCS com sistemas de nível superior — entende a arquitetura de segmentação IT/OT (DMZ industrial) — diagnostica problemas de comunicação em redes industriais','Modelo OSI aplicado à automação industrial: onde cada protocolo industrial se encaixa — Modbus/RTU (camadas 1–2), PROFIBUS DP (camada 2), PROFINET/EtherNet/IP (camadas 1–4), OPC UA (camadas 5–7) · PROFINET e EtherNet/IP: topologias de rede, gerenciamento de I/O distribuído, diagnóstico de comunicação com ferramentas de rede, integração de I/O remoto com DCS e CLP · Modbus TCP/IP: o protocolo de integração mais onipresente — como conectar analisadores, medidores de energia, CLPs de terceiros e instrumentos inteligentes via Modbus · OPC UA no contexto de processo: servidor OPC UA em DCS e CLPs, subscrição de dados (Publish/Subscribe), modelo de informação de processo, integração com Historian e MES · Modelo de segurança OT: pirâmide ISA-95, zonas de segurança IEC 62443, DMZ industrial (nível 3.5), segmentação IT/OT com firewall — por que o DCS não pode estar direto na rede corporativa · Diagnóstico de redes industriais: wireshark para captura de pacotes Modbus/TCP e OPC UA, PROFIBUS tester para diagnóstico de rede PA/DP, identificação de colisões, latência e perda de pacote · Virtualização em automação: SCADA em máquina virtual, contêineres Docker para aplicações de borda — a nova realidade da infraestrutura de automação','70–90 horas','["ISA-95", "IEC 61784", "IEC 62541", "IEC 62443"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(56,105,'Avançado · Perfil de entrada: A2 + R1 concluídos',3,'Compreende a arquitetura funcional de um MES (Manufacturing Execution System) e como ele se conecta ao nível de controle (SCADA/DCS) e ao nível de gestão (ERP/SAP) — configura integrações básicas entre SCADA e banco de dados de processo — cria relatórios de produção e KPIs operacionais — apoia implantações de MES em plantas de processo','ISA-95 (IEC 62264) revisitado em profundidade: os 5 níveis da pirâmide de automação e as interfaces entre eles — especialmente as interfaces L2↔L3 (SCADA↔MES) e L3↔L4 (MES↔ERP) · MES para processo contínuo: diferença entre MES para manufatura discreta (Atlas Mecatrônica) e MES para processo contínuo — batch reporting, genealogia de produto, energy management, LIMS (Laboratory Information Management System) · AVEVA MES / Aveva System Platform como MES: configuração de modelos de equipamento, sequências de operação, integração com Historian e ERP · Ignition como plataforma MES: módulos EAD do Ignition University para Reporting, Transaction Groups e Mobile — a abordagem "SCADA que vira MES" que está crescendo em plantas de médio porte · SAP PP/QM para automação: como dados de processo chegam ao SAP — interfaces com BAPI, RFC e REST API — o que o técnico de automação precisa entender sem ser analista SAP · KPIs de processo: OEE (Overall Equipment Effectiveness), rendimento global, disponibilidade de processo — como calcular a partir de dados do SCADA e Historian · SQL para automação: consultas básicas ao banco de dados de processo — SELECT, WHERE, JOIN, GROUP BY — para extrair dados do Historian e criar relatórios operacionais','70–90 horas','["ISA 88", "ISO 22400", "ISA-95", "IEC 62264"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(57,106,'Avançado · Perfil de entrada: A1 + I1 concluídos — compreensão básica de risco industrial (NR-13, elementos de HAZOP são diferenciais)',3,'Compreende os fundamentos da segurança funcional conforme IEC 61511 — entende o ciclo de vida de segurança e onde cada disciplina atua — diferencia SIS de BPCS (Basic Process Control System) e entende por que não podem compartilhar infraestrutura — conhece Safety PLCs (SIL 2/3) e sua diferença em relação a CLPs padrão — participa de proof tests e testes de comprovação de laços SIS','Conceito de risco e camadas de proteção (LOPA): o framework que define quando um SIS é necessário — a diferença entre um sistema de controle que evita incidentes e um sistema de segurança que mitiga consequências quando o controle falha · IEC 61511: o padrão internacional de segurança funcional para o setor de processo — sua estrutura (partes 1, 2, 3), ciclo de vida de segurança (SLC), e o que se aplica ao técnico de automação versus ao engenheiro de projeto · Safety Integrity Level (SIL): o que é, como é determinado (HAZOP + LOPA) e o que SIL 1, 2, 3 significam na prática — especificamente, quais requisitos impõem ao hardware e ao software · BPCS versus SIS: por que o mesmo I/O não pode ser compartilhado, por que o mesmo CLP não pode fazer controle de processo e intertravamento de segurança, e como a camada de controle é separada da camada de segurança · Safety PLCs certificados: Siemens S7-1500F, Rockwell GuardLogix, Hima HIMatrix/HIQuad — arquitetura 1oo2D, diagnósticos automáticos (DC — Diagnostic Coverage) e como isso difere de um CLP padrão · Lógica de intertravamento SIS: como traduzir um IEC 61511 SRS (Safety Requirements Specification) em lógica de CLP de segurança — blocos lógicos, intertravamentos, timers de confirmação · Proof tests (testes de comprovação): o que é, por que é obrigatório, frequência conforme SIL — procedimento para testar um laço SIS sem parar a planta (bypass management) · Gestãode bypass e override: os controles obrigatórios para que um laço SI','90–120 horas','["NR-13", "IEC 62061", "ISA 84.00.01", "IEC 61511", "IEC 61508"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(58,107,NULL,NULL,'Compreende a superfície de ataque de ambientes OT industriais (SCADA, DCS, PLC) — implementa controles de segurança conforme IEC 62443 e NIST SP 800-82 — configura zonas e condutos de segurança — utiliza ferramentas de monitoramento de tráfego OT (Claroty, Nozomi, Dragos) em modo de observação — aplica conceitos de defesa em profundidade na arquitetura de rede industrial — elabora planos básicos de resposta a incidentes em sistemas de controle industrial.','Landscape de ameaças OT: diferenças entre cibersegurança IT e OT — impacto em disponibilidade de processo, segurança operacional e integridade física · IEC 62443 — Segurança de Redes e Sistemas de Automação Industrial: estruturada série (2-1, 2-3, 3-2, 3-3, 4-2), SL (Security Level) 1–4, zonas e condutos, requirements por componente · NIST SP 800-82 (ICS Security): guia prático, arquitectura de referência, controles aplicáveis a SCADA, DCS e PLCs · Ameaças conhecidas a ICS: análise de incidentes reais (Stuxnet, Industroyer/Crashoverride, LockerGoga, TRITON/TRISIS) — o que cada ataque comprometeu e o que poderia ter prevenido · Hardening de redes OT: segmentação com firewall industrial (Fortinet, Palo Alto OT), DMZ industrial, lista de permissões de protocolo, remoção de serviços desnecessários · Monitoramento passivo de tráfego OT: uso de plataformas Claroty (Team82), Nozomi Networks Guardian e Dragos Platform — detecção de anomalias sem interferir no processo · Gestãode vulnerabilidades em OT: CVE para componentes industriais, ICS-CERT/CISA advisory, processo de patch management em ambientes com SLA de disponibilidade 24/7 · Segurança de acesso remoto: VPN para acesso de manutenção, jump server, MFA em ambientes OT — controle de terceiros e fornecedores','120 h · Nível: Avançado','["IEC 62443"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(59,108,NULL,NULL,'Elabora e executa plano de resposta a incidentes específico para ambientes OT — realiza triagem de eventos em SIEMs com dados OT — coordena recuperação de sistemas de controle pós-incidente preservando segurança operacional — documenta incidentes e lições aprendidas conforme NIST CSF — compreende interface entre resposta OT e Plano de Continuidade do Negócio.','ICS Incident Response: diferença entre IR em IT e OT — preservação de disponibilidade de processo, coordenação com sala de controle, impacto de desligar um PLC em processo contínuo · NIST Cybersecurity Framework aplicado a OT: Identify, Protect, Detect, Respond, Recover — mapeamento para controles IEC 62443 · Coleta forense em ICS: logs de PLC, SCADA Historian, switches industriais — o que coletar sem impactar o processo · Backups e recuperação: backup de programas de PLC (exportação de projeto), configuração de DCS, tags SCADA — plano de recuperação testado · Tabletop exercises para ICS: como conduzir exercícios de crise envolvendo equipes de automação, operação, TI e segurança · Integração OT-SOC: como um SOC trata alertas OT diferentes de IT, enrichment de alertas com contexto de processo','80 h · Nível: Avançado','[]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(60,110,NULL,NULL,'Identifica e seleciona instrumentos de medição de pressão, temperatura, nível e fluxo para aplicações em processos industriais — interpreta P&IDs conforme ISA 5.1 — conecta transmissores com sinal 4–20 mA e HART — realiza comissionamento básico de instrumentos de campo.','P&ID e simbologia ISA 5.1: leitura e interpretação completa de diagramas de instrumentação e tubulação — símbolos de instrumentos, linhas de processo e de instrumento, identificação de tags (FT, PT, TT, LT, AT), válvulas de controle e controladores · Transmissores de pressão: princípio de medição piezorresistivo (Kistler, PCB) e capacitivo (Endress+Hauser Deltabar, Emerson Rosemount 3051), zero e span, supressão e elevação de zero, manifolds de 3 e 5 vias · Transmissores de temperatura: termopar (tipos J, K, S, R, E, T — seleção por faixa e ambiente), RTD (PT100/PT1000 em 2, 3 e 4 fios), transmissores de temperatura com saída HART — fontes de erro, seleção e instalação · Medição de vazão: diferencial de pressão (placa de orifício, tubo Pitot, Annubar), magnético (Endress+Hauser Promag, Siemens MAG), vórtice, Coriolis (Micro Motion), ultrassônico — princípios, aplicações, limitações, instalação e comissionamento · Medição de nível: pressão hidrostática (borbulhador, selagem capilar), ultrassônico, radar FMCW (Emerson Rosemount 5408, VEGA VEGAPULS), guia de ondas (GWR), bóia e deslocador — seleção por tipo de fluido, pressão e temperatura de processo · Sinal 4–20 mA e loop de corrente: alimentação de 24 VDC, resistência de loop, diagnóstico de sinal aberto e curto-circuito, uso de clamp meter e multímetro de loop · Comissionamento básico: loop check físico (verificação de fiação, identificação de polaridade), configuração via HART Communicator (handheld), ajuste de zero e span,','120 h · Nível: Básico · Pré-requisito: Matemática básica, fundamentos de eletricidade','["ISA 5.1"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(61,111,NULL,NULL,'Realiza calibração de transmissores de pressão, temperatura e sinais elétricos (4–20 mA) utilizando calibradores portáteis (Fluke 754, Beamex MC6) — calcula incerteza de medição — emite e interpreta certificados de calibração rastreáveis — aplica os requisitos básicos da ISO/IEC 17025 em rotinas de campo.','Conceitos de metrologia: valor verdadeiro, erro, incerteza de medição, rastreabilidade metrológica, padrão de referência, calibração versus verificação · Cadeia de rastreabilidade metrológica: BIPM → INMETRO (RNM) → Laboratórios RBC → laboratório de campo — como certificados de calibração rastreáveis garantem validade legal e conformidade regulatória · Incerteza de medição (VIM): incerteza padrão, incerteza combinada, fator de abrangência, expressão de resultados conforme GUM (Guide to the Expression of Uncertainty in Measurement) — cálculo simplificado para instrumentistas de campo · Calibração de transmissores de pressão: uso de calibrador de pressão (Fluke 700 G, Beamex MC6-P) — procedimento de 5 pontos, histerese, erro de linearidade, ajuste de zero e span · Calibração de transmissores de temperatura: uso de calibrador de temperatura (Fluke 724, Beamex MC6-T) — simulação de termopar e RTD, injeção de sinal, tabelas de termopar (ITS-90) · Calibração de sinais de processo 4–20 mA e HART: Fluke 754/789 — procedimento de loop de corrente, teste de comunicação HART, leitura de variáveis de dispositivo · Software de gestãode calibração: Beamex CMX Enterprise e Fluke Calibration Management — registro de ativos de instrumentação, plano de calibração preventiva, rastreabilidade de resultados · ISO/IEC 17025 introdutória: escopo de acreditação, requisitos de gestão (imparcialidade, confidencialidade), requisitos técnicos (pessoal, equipamento, rastreabilidade, validade dos resulta','80 h · Nível: Básico · Pré-requisito: F1','["IEC 17025"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(62,112,NULL,NULL,'Especifica e instala instrumentação para processos contínuos de O&G e petroquímica — lê e executa pacotes de instrumentação (datasheets, hook-up drawings, I/O lists) — comissiona malhas de controle PID de nível, pressão, fluxo e temperatura — realiza diagnóstico de válvulas de controle em campo — aplica práticas de segurança de instrumentação conforme IEC 61511.','Malhas de controle industrial: malha PID básica — controlador, transmissor, elemento final de controle (válvula) — configuração de parâmetros PID (PB, Ti, Td) — cascata — feedforward — split range · Válvulas de controle: construção (globo, borboleta, esfera, cage, ângulo), tamanho (Cv), características de fluxo (linear, raiz quadrada, de percentagem igual), cavitação e flashing · Atuadores e posicionadores: atuador pneumático (mola x membrana, cilindro duplo efeito), posicionador analógico (Fisher, Samson), posicionador HART/digital (Fisher DVC6200, Emerson Fisher Fieldvue) — configuração e ajuste de viagem · Documentação de instrumentação: datasheet de instrumento, hook-up drawing, installation detail, loop diagram — leitura e execução · Sistemas de intertravamento (SIS): conceito de SIL (Safety Integrity Level), diferença entre BPCS (sistema de controle básico) e SIS (sistema instrumentado de segurança), pressostato de alta/alta e chave de nível — aplicação em petroquímica · Instrumentação em área classificada: zonas de explosividade (Z0, Z1, Z2, M1, M2), métodos de proteção (Ex d, Ex e, Ex ia, Ex n) — seleção de instrumento e instalação conforme ABNT NBR IEC 60079 · Comissionamento de malhas: pre-commissioning checklist, cold loop check, hot loop check, functional test de válvula de controle, documentação de punch list · Normas e padrões: API RP 554 (Process Control and Safety Instrumentation for Petroleum Refineries) · ISA-TR84.00.04 (guideline SIS)','120 h · Nível: Pleno · Pré-requisito: F1 + F2','[]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(63,113,NULL,NULL,'Compreende os princípios de operação de analisadores on-line (pH, O₂, COT, analisadores de processo), realiza manutenção preventiva básica e interpretação de resultados — opera e efetua calibrações rotineiras de cromatógrafos a gás industriais — entende a aplicação de analisadores em controle de qualidade de produto e em sistemas de segurança ambiental.','Analisadores de processo: tipos principais (pH/ORP, condutividade, O₂ dissolvido, turbidez, COT, espectrofotômetros NIR) — princípios de medição, calibração rotineira e manutenção preventiva · Cromatografia a gás industrial (GC on-line): princípio de separação cromatográfica, detector TCD/FID, válvula de injeção, coluna cromatográfica, resultado — aplicação em análise de gás natural (BTU, composição), correntes de refino e emissões atmosféricas · Analisadores de gás industriais: medição de O₂ (paramagnético, eletroquímico, zircônia), CO, CO₂, H₂S, SO₂ — seleção por aplicação, calibração com gás padrão certificado · Sistema de condicionamento de amostra: shelter de analisador, sistema de tomada de amostra (fast loop), filtros, heated lines, separador gás-líquido — a importância do condicionamento para a qualidadeda análise · Qualificação e calibração: curva de calibração multipontos, padrões primários versus de trabalho, frequência de calibração, gestãode gás padrão certificado · Integração com sistemas de controle: saída 4–20 mA e sinais digitais (Modbus, Foundation Fieldbus), comunicação com DCS e SCADA, alarmes de qualidade de produto e de analisador','80 h · Nível: Pleno · Pré-requisito: F1 + P1','[]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(64,114,NULL,NULL,'Realiza diagnóstico de falhas em malhas de controle PID (válvula travada, transmissor com deriva, oscilação de processo) — utiliza diagnóstico integrado de posicionadores HART (Fisher DVC, Emerson AMS, ValveLink) — aplica técnicas de manutenção centrada em confiabilidade (RCM) para instrumentos de campo — planeja e executa rotina de manutenção preventiva de instrumentação conforme estratégia de confiabilidade da planta.','Diagnóstico de malhas de controle: análise de resposta ao degrau, identificação de válvula travada (stiction) e não-linearidade, transmissor com deriva, controlador saturado — como distinguir falha de instrumento de falha de processo · Diagnóstico de válvulas inteligentes (HART): uso de ValveLink (Emerson) e AMS Device Manager — teste de assinatura da válvula, diagnóstico de stiction, desgaste de gaxeta, relatório de condição · Manutenção preditiva de instrumentos: plano de manutenção baseado em confiabilidade para instrumentos (FMEA de instrumento), intervalos de calibração baseados em desempenho histórico, criticidade por SIL e função de segurança · Diagnóstico de transmissores HART: leitura de variáveis de dispositivo (PV, SV, TV, QV), status de device (NE 107), diagnóstico de entupimento de impulso, verificação de selagem capilar · Gestãode ativos de instrumentação: SAP PM (Plant Maintenance) para emissão e gestãode ordens de manutenção, CMMS — registro de histórico de falhas e manutenções de instrumentos · RCM para instrumentação: conceitos de Reliability Centered Maintenance aplicados a instrumentos — funções, falhas funcionais, modos de falha, efeitos (FMEA) e tarefas de manutenção adequadas · Análise de causa raiz de falhas: metodologia RCA (5-Whys, Ishikawa) aplicada a falhas de instrumentação — como documentar, investigar e prevenir recorrências','100 h · Nível: Pleno · Pré-requisito: F1 + P1','[]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(65,115,NULL,NULL,'Implanta e mantém sistema de gestão da qualidade em laboratório de calibração conforme ISO/IEC 17025:2017 — elabora procedimentos de calibração, documentação de incerteza e relatórios de ensaio — prepara laboratório para auditoria de acreditação RNCA/INMETRO — conduz auditorias internas de sistema de gestão — compreende o papel da acreditação na cadeia de conformidade regulatória.','ISO/IEC 17025:2017 em profundidade: estruturada norma (requisitos de gestão + requisitos de processo), interpretação de cada cláusula, diferenças em relação à versão 2005, impacto na prática laboratorial diária · Sistema de gestão do laboratório: política da qualidade, manual da qualidade, procedimentos documentados (SOP), registros de qualidade — nível de documentação exigido por INMETRO/CGCRE · Controle de equipamentos de medição: rastreabilidade do padrão de trabalho ao RNM, frequência de calibração, ajuste vs. verificação, equipamento fora de especificação (OOT — Out Of Tolerance), status de calibração · Validação de métodos: verificação de método normativo, incerteza de medição conforme EA-4/02, comparação interlaboratorial, ensaios de proficiência (PT) da RNCA · Auditoria interna de laboratório: planejamento, execução e relatório de auditoria interna ISO 19011 — não-conformidades (NC), ações corretivas (AC), eficácia — preparação para auditoria de acreditação INMETRO/CGCRE · Relatório de calibração: emissão de certificado conforme ILAC-G8, expressão de incerteza, declaração de conformidade (com e sem risco do consumidor), assinatura técnica responsável · Gestãode reclamações e melhoria contínua: tratamento de reclamações de clientes, ações preventivas, indicadores de desempenho do laboratório, revisão de gestão','80 h · Nível: Avançado · Pré-requisito: F2','["IEC 17025"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(66,116,NULL,NULL,'Configura e diagnostica instrumentos com protocolo HART 7 (multivariável, WirelessHART), Foundation Fieldbus H1 e PROFIBUS PA em plantas de processo — utiliza ferramentas de gestãode ativos (AMS, PACTware) para diagnóstico remoto — compreende a arquitetura e o comissionamento de Ethernet-APL — a nova infraestrutura de rede para instrumentação digital de campo.','HART 7 em detalhe: estrutura do protocolo (FSK sobre 4–20 mA), comandos universais e específicos, multidrop HART, WirelessHART (IEC 62591) — topologia em malha, gateway, bateria, aplicações de telemetria remota · Foundation Fieldbus H1: topologia de barramento, sementação de rede, blocos de função (AI, AO, PID no campo), interoperabilidade, comissionamento com Fieldbus Foundation tools · PROFIBUS PA: diferenças em relação ao DP, conector, topologia de barramento intrínseco de segurança, coupling de PA ao DP (DP/PA Link, DP/PA Coupler), diagnóstico com ProfiTrace · Ethernet-APL (Advanced Physical Layer): o novo paradigma — porta blindada de 2 fios, 10 Mbps, alimentação no cabo, topologia de trunk e spur, integração com PA-DIM (PROFINET) e FF-HSE — por que vai substituir gradualmente Foundation Fieldbus e PA · Gestãode ativos com PACTware (gratuito): conexão a instrumentos via HART e PROFIBUS, leitura de parâmetros de dispositivo, diagnóstico conforme NE 107 (NAMUR), configuração de blocos de função · Análise de barramento Fieldbus: ferramentas de diagnóstico (Relcom FBT-6, Softing FG-100) — identificação de ruído, reflectância, dispositivos mal comissionados · Tendências: APL (Ethernet-APL), OPC UA FX para campo, NAMUR Open Architecture (NOA) — a instrumentação digital convergindo com a pirâmide de automação OPC UA','80 h · Nível: Avançado · Pré-requisito: F1 + F2 · Referência cruzada: Atlas Automação I2','[]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(67,120,'Iniciante · Perfil de entrada: Qualquer trabalhador ou estudante de ensino médio',1,'Compreende os conceitos fundamentais de logística e supply chain — conhece os modais de transporte e suas aplicações industriais — entende a estruturada cadeia de suprimentos industrial (fornecedor de insumos → planta → distribuição → cliente) — domina a terminologia logística usada em empresas de O&G','Conceito de logística industrial: do just-in-time ao just-in-case — como as estratégias mudaram com a pandemia e a disrução de supply chains globais · Os cinco grandes fluxos da logística: materiais, informações, financeiro, pessoas e reverso (logística reversa) · Modais de transporte: rodoviário, ferroviário, aquaviário (cabotagem e longo curso), dutoviário e aeroviário — vantagens, limitações, custo-distância e aplicações em O&G · Cadeia de suprimentos industrial: conceito de cadeia estendida, gestãode risco (SCRM — Supply Chain Risk Management), reshoring e nearshoring pós-COVID · Terminologia: incoterms 2020 (FOB, CIF, DDP, EXW, CFR — os mais usados em importação de equipamentos para O&G), lead time, OTIF (On Time In Full), fill rate, stockout · Armazenagem: tipos de armazém (blocado, porta-paletes, drive-in, mezanino, temperatura controlada), layout e fluxo de materiais · Documentação logística básica: nota fiscal, romaneio de carga, packing list, knowledge of lading (BL/AWB), certificado de origem · Logística reversa industrial: gestãode resíduos, retorno de embalagens, descarte de materiais obsoletos conforme legislação ambiental','50–70 horas','["ABNT NBR 14724"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(68,121,'Pleno · Perfil de entrada: F1 concluído',2,'Gerencia o ciclo completo de estoques industriais — recebimento, inspeção, armazenagem, separação e expedição — aplica as metodologias de classificação e controle de estoques (curva ABC, XYZ, criticidade) — configura e opera um WMS (Warehouse Management System) básico — realiza inventário cíclico e acurácia de estoque — calcula estoques mínimos, máximos e pontos de pedido','Ciclo de gestãode estoques: necessidade → requisição → ordem de compra → recebimento → inspeção → armazenagem → separação (picking) → expedição — e onde cada etapa pode falhar em plantas industriais · Curva ABC de estoques: critérios de classificação (valor de consumo, frequência, criticidade), análise ABC clássica e ABC multicritério para sobressalentes de manutenção · Matriz de criticidade para sobressalentes: por que a curva ABC pura não funciona para peças de reposição de planta — cruzamento de criticidade operacional × tempo de reposição (lead time) × custo de parada · Estoque mínimo de segurança: cálculo por desvio padrão da demanda × nível de serviço desejado — aplicação prática para almoxarifado industrial · Ponto de pedido e lote econômico de compra (LEC/EOQ): fórmulas, premissas e limitações — como adaptar para itens industriais com demanda irregular · WMS (Warehouse Management System): conceito, funcionalidades (recebimento, endereçamento, picking, inventário), integração com ERP — como o WMS muda a operação de um almoxarifado industrial · Acurácia de estoque e inventário cíclico: por que acurácia abaixo de 98% gera paradas inesperadas em planta — metodologia de inventário rotativo e tratamento de divergências · FIFO, FEFO, LIFO: quando usar cada método em contextos industriais (peças de borracha, reagentes com prazo de validade, materiais a custo de reposição)','80–100 horas','["NR-11", "ABNT NBR 14724", "ISO 9001", "ABNT NBR 7500"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(69,122,'Pleno · Perfil de entrada: F1 concluído',2,'Executa o ciclo completo de compras industriais — da requisição ao pagamento — elabora solicitações de cotação (RFQ) e analisa propostas de fornecedores — qualifica e avalia fornecedores com critérios técnicos e comerciais — opera SAP MM para gestãode requisições, ordens de compra e pedidos de serviço — compreende os fundamentos de contratos de fornecimento e SLAs','Ciclo de procurement industrial: requisição de material (RM) → aprovação → RFQ (Request for Quotation) → análise de propostas → ordem de compra → follow-up → recebimento → pagamento — e as armadilhas em cada etapa · Tipos de compra: spot (compra única de mercado), contrato de fornecimento (preço fixo, índice de reajuste), acordo de nível de serviço (SLA), consignação de estoque e vendor-managed inventory (VMI) · Especificação técnica de materiais: diferença entre especificação funcional e especificação de produto — como uma especificação mal feita atrasa projetos e causa retrabalho · Qualificação de fornecedores: critérios técnicos (capacidade produtiva, certificações ISO/API), financeiros (solidez, histórico de crédito) e de HSE (conformidade regulatória) · Avaliação de desempenho de fornecedores: KPIs (OTIF, qualidade de recebimento, conformidade documental), scorecards e planos de ação corretiva · SAP MM — Módulo de Compras: requisições de compra (ME51N), pedidos de compra (ME21N), contratos de fornecimento (ME31K), análise de preços (ME49) · Incoterms 2020 em profundidade: responsabilidades de frete, seguro, desembaraço aduaneiro e risco por incoterm — o que cada um significa para o almoxarife que vai receber a mercadoria · Compras sustentáveis: critérios ESG na seleção de fornecedores — como as operadoras de O&Gestão incorporando critérios ambientais e de trabalho decente em seus processos de procurement','80–100 horas','["ISO 20400", "ISO 44001"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(70,123,'Pleno · Perfil de entrada: F1 + G2 concluídos',2,'Elabora o PCP (Planejamento e Controle da Produção) de uma unidade industrial — executa o processo de S&OP (Sales & Operations Planning) em nível básico — opera o módulo de MRP (Material Requirements Planning) no SAP PP para geração de ordens planejadas — calcula capacidade produtiva e identifica gargalos — elabora a programação de produção a curto prazo','Hierarquia do planejamento de produção: planejamento estratégico (S&OP anual) → planejamento tático (MPS — Master Production Schedule, trimestral) → planejamento operacional (MRP, semanal) → programação e sequenciamento (diário) · S&OP (Sales & Operations Planning): o processo que alinha demanda, capacidade e estoques — reunião mensal de S&OP, papéis, dados de entrada e saídas esperadas · Previsão de demanda industrial: métodos (média móvel, suavização exponencial, sazonalidade) e limitações em ambientes industriais de baixo volume e alta variabilidade · MRP (Material Requirements Planning): cálculo de necessidades líquidas, explosão de BOM (Bill of Materials), geração de ordens de compra e produção planejadas — conceito antes do SAP · SAP PP — Planejamento de Produção: estrutura de dados (material master, BOM, routing, work center), execução de MRP (MD01/MD02), análise de resultado (MD04) · Capacidade produtiva: cálculo de capacidade disponível, carregamento de recursos (máquinas, mão de obra), identificação de gargalos pela Teoria das Restrições (TOC — Theory of Constraints) · Programação de manutenção como supply chain: como o SAP PM (Plant Maintenance) se conecta com o SAP MM para geração automática de requisições de sobressalentes · SIOP em O&G: como as refinarias e plataformas adaptam o S&OP para o ambiente de produção contínua — paradas programadas (turnarounds) como grandes eventos de planejamento','80–100 horas','["ABNT NBR 15645", "ISO 9001"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(71,124,'Avançado · Perfil de entrada: G1 + P1 concluídos',3,'Aplica os princípios lean ao longo da cadeia de suprimentos industrial — mapeia o fluxo de valor (VSM) de processos logísticos — identifica e elimina os 8 desperdícios em armazéns, compras e planejamento — implementa ferramentas lean no almoxarifado (5S, kanban, nivelamento) — conduz eventos kaizen de melhoria em processos de supply chain','Pensamento enxuto (lean thinking) na supply chain: os 5 princípios do lean aplicados à logística — valor, fluxo de valor, fluxo contínuo, puxada e perfeição · Os 8 desperdícios (TIMWOODS) em supply chain: superprodução de ordens, transporte excessivo, inventário desnecessário, movimento de pessoas, espera, superprocessamento, defeitos e subutilização de pessoas · VSM (Value Stream Mapping) logístico: mapeamento do fluxo de materiais e informações desde o fornecedor até o ponto de uso — identificação de lead time de valor agregado versus lead time total · Kanban industrial: tipos (kanban de produção, de retirada, de sinal), dimensionamento do número de cartões, implementação em almoxarifados e linhas de produção · 5S em armazéns industriais: Seiri, Seiton, Seiso, Seiketsu, Shitsuke — aplicação específica para almoxarifados e bases de apoio logístico · Kaizen de supply chain: estrutura de um evento kaizen (5 dias), definição de escopo, mapeamento de situação atual, proposta de futuro, implementação e sustentação · Milk run e rotas de coleta programada: como substituir pedidos emergenciais por rotas de coleta planejadas — redução de fretes spot e custo de inventário · Custo total de propriedade (TCO — Total Cost of Ownership): por que o preço de compra é apenas uma parcela do custo real — frete, armazenagem, qualidade, lead time e risco de fornecedor','60–80 horas','["ISO 45001", "ISO 9001"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(72,125,'Avançado · Perfil de entrada: G1 + G2 concluídos — conhecimento básico do setor de O&G é diferencial',1,'Gerencia a logística de suporte offshore — programação de supply boats, manifesto de carga para plataforma, handling em base de apoio — gerencia materiais críticos e sobressalentes em plantas de O&G com metodologia de criticidade — opera em ambiente Repetro (regime aduaneiro especial) — coordena a logística de grandes turnarounds — compreende as regulamentações específicas do setor','Logística offshore: a cadeia de apoio a plataformas — base de apoio → supply boat → plataforma → retorno de resíduos e equipamentos defeituosos · Manifesto de carga offshore: documentação obrigatória para embarque em supply boat (MARPOL Annex V para resíduos, ISPS Code para segurança, Marinha do Brasil — NORMAM) · Bases de apoio ao offshore no Brasil: Macaé (RJ), Terminal de Açu (RJ), Madre de Deus (BA), Suape (PE) — estrutura, operações e logística de helicoportagem · Gestãode materiais críticos em O&G: a metodologia que vai além da curva ABC — matriz de criticidade operacional × tempo de reposição × consequência de stockout · Sobressalentes: classificação em consumíveis, rotacionáveis, de segurança e de capital — como cada categoria é gerenciada diferente no ERP · Repetro (Regime Aduaneiro Especial para petróleo): como funciona, quais equipamentos se qualificam, responsabilidades do operador logístico e do almoxarife em relação à Receita Federal · Turnaround logistics (T/A): o maior evento de supply chain de uma refinaria — planejamento com 18–24 meses de antecedência, warehouse temporário de turnaround, just-in-time de itens críticos durante a parada · MARPOL e gestãode resíduos offshore: categorias de resíduo a bordo, segregação, manifesto de retorno — responsabilidade do técnico de logística embarcado · Normas Petrobras de suprimentos: COEST (Condições Gerais de Compra e Contratação), SAP PEXP e processos de procurement Petrobras — o maior comprador do Brasil','90–120 horas','["NR-34"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(73,126,'Avançado · Perfil de entrada: F1 + G2 concluídos',3,'Classifica produtos perigosos conforme as regulamentações internacionais e brasileiras — emite e verifica a documentação de transporte de produtos perigosos (DPP, DAE, ESD) — orienta equipes de manuseio e transporte — identifica responsabilidades legais — gerencia o transporte de produtos perigosos comuns em O&G (gases inflamáveis, ácidos, explosivos sísmicos, fontes radioativas para wireline)','Sistema de classificação ONU de produtos perigosos: 9 classes de risco, identificação pelo número ONU (UN Number), rótulo e painel de segurança — o alfabeto do transporte de materiais perigosos · Regulamento IMDG (International Maritime Dangerous Goods): o código que rege o transporte de produtos perigosos por via marítima — aplicação no transporte de cargas de O&G entre portos e plataformas · Regulamento ADR (transporte rodoviário internacional) e legislação ANTT/ABNT para transporte rodoviário nacional de produtos perigosos: documentação (FISPQ, ficha de emergência), veículo adequado, treinamento do motorista · IATA DGR (Dangerous Goods Regulations): transporte de produtos perigosos por via aérea — crítico para o transporte de amostras, equipamentos eletrônicos com bateria e ferramentas de wireline em helicópteros offshore · Classes críticas em O&G: Classe 1 (explosivos sísmicos), Classe 2 (gases: GNL, H₂S, CO₂), Classe 3 (líquidos inflamáveis — petróleo, diesel), Classe 5 (oxidantes: H₂O₂), Classe 6.1 (tóxicos), Classe 7 (radioativos — fontes de wireline e well logging), Classe 8 (corrosivos: ácidos de estimulação) · FISPQ (Ficha de Informações de Segurança de Produto Químico): leitura, interpretação e uso em emergências — o documento que o técnico de logística deve conhecer para cada produto que manuseia · Plano de resposta a emergências em transporte: PAE (Plano de Ação de Emergência), comunicação com Disque Acidente (0800 do IBAMA), DECON e corpo de bombeiros','70–90 horas','["NR-20", "ABNT NBR 7500"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56'),
(74,127,'Avançado · Perfil de entrada: G1 + P1 concluídos — noções básicas de informática industrial',3,'Compreende a arquitetura tecnológica de um supply chain digital — WMS com RFID, TMS com roteirização, rastreabilidade com QR Code e IoT de ativos — configura integrações básicas entre WMS e ERP (SAP MM) — analisa KPIs de supply chain em dashboards — apoia projetos de transformação digital em logística industrial','Supply Chain 4.0: como IoT, big data, inteligência artificial e blockchain estão transformando a logística industrial — casos reais em O&G, mineração e petroquímica · WMS (Warehouse Management System) digital: funcionalidades avançadas — recebimento com conferência eletrônica, endereçamento dinâmico, picking por voz (voice picking), expedição com verificação por peso · RFID na logística industrial: tecnologia UHF RFID para rastreamento de equipamentos e ferramentas em plataformas e plantas, RFID HF para controle de ciclo de vida de cilindros de gás e extintores · GS1: padrões de rastreabilidade — código de barras 1D (EAN-13, Code 128), 2D (QR Code, DataMatrix, GS1 DataBar), RFID (EPC/RFID Gen2) — integração com ERP para rastreabilidade de lote e série · TMS (Transportation Management System): roteirização otimizada, gestãode fretes, tracking de cargas em tempo real — como o TMS reduz custo logístico em 15–25% · IoT de ativos: rastreamento de equipamentos em campo com GPS/RFID, gestãode ferramentas em projetos offshore, localização de ativos em armazéns amplos com UWB (Ultra-Wideband) · Análise de dados de supply chain: KPIs em Power BI ou Google Data Studio — OTIF, acurácia de estoque, giro de estoque, custo de frete por tonelada-km, lead time de suprimento · Blockchain em supply chain: rastreabilidade de origem de materiais, contratos inteligentes para pagamento automático — onde está hoje e o que é promessa de médio prazo','70–90 horas','["IEC 15962", "ISO 28000", "IEC 18000"]','| Fonte | Tipo | Conteúdo | Acesso |','2026-06-28 14:29:56');
