INSERT INTO sector_programs (id,company_id,sector_id,programa,formato,publico,custo,detalhe,industry_sector_id) VALUES
(1,1,1,'Programa de Formação Profissional (PFP)','Presencial + on the job training','Comunidades no entorno das operações; primeiro emprego','**Gratuito** + bolsa de até R$ 2.200/mês','Duração: ~18 meses; parceria SENAI; cursos: Elétrica, Mecânica, Soldagem, Eletromecânica, Operação Ferroviária; seletiva online',1),
(2,1,1,'Programa Qualificar','Presencial','Moradores de municípios próximos às operações (ex: Caeté, Santa Bárbara)','**Gratuito**','495 vagas por ciclo; cursos técnicos e de segurança/operação industrial; objetivo: empregabilidade regional',1),
(3,1,1,'EAD Agro c/ ManejeBem','Online (EAD) + suporte por WhatsApp','Produtores rurais familiares no Pará','**Gratuito**','Parceria Vale + ManejeBem (startup ESG); cursos: cooperativismo, gestão financeira rural, agroecologia',1),
(4,438,1,'Cursos para Comunidades / Força Local','Presencial (noturno)','Moradores +18 anos com ensino médio em MG e ES','**Gratuito**','Parceria SENAI (Mariana, Anchieta) e CEDTEC (Guarapari); >2.000 formados desde 2022; 43% dos alunos absorvidos pela Samarco ou contratadas',1),
(5,438,1,'Qualificação Técnica — ciclos semestrais','Presencial','Moradores de Mariana, Ouro Preto, Catas Altas, Santa Bárbara (MG); Anchieta, Guarapari, Piúma (ES)','**Gratuito**','Cursos: Mecânica Industrial, Soldador Multiprocesso, Instrumentação Industrial, Técnico de Mineração, Técnico de Automação, Operador de Processo, Eletrotécnica, Qualificação em Solda; carga horária: 160h–18 meses conforme curso',1),
(6,438,1,'Cursos 2026 — último ciclo mapeado','Presencial (noturno)','Residentes em Anchieta, Guarapari e Piúma (ES)','**Gratuito**','105 vagas; cursos: Pedreiro de Alvenaria, Instrumentação Industrial, Eletricista Industrial; início março/2026',1),
(7,3,1,'Programa de Qualificação Profissional','Presencial (com portal de inscrições próprio)','Comunidades no entorno do Minas-Rio (Conceição do Mato Dentro, Alvorada de Minas, Dom Joaquim, Serro, Congonhas do Norte – MG)','**Gratuito**','Parceria SENAI / IEL-FIEMG; 140 vagas por ciclo; cursos: Elétrica Industrial, Mecânica de Máquina Industrial, Mecânica de Equipamento Móvel, Operador/Mantenedor, Operação Caminhão Komatsu 830E; vagas afirmativas: mulheres, PcD, negros, LGBTQIA+',1),
(8,3,1,'Programa de Aprendizagem Básica','Presencial (18 meses)','Jovens 17 anos, 2º ano do Ensino Médio','**Gratuito**','Parceria Sesi/Senai; capacitação em Operação de Mina, Tratamento de Minério, Operação de Equipamentos de Beneficiamento',1),
(9,3,1,'Programa Crescer','Presencial (noturno)','Jovens de municípios no entorno das operações (ex.: Niquelândia-GO)','**Gratuito**','Foco: autoconhecimento, orientação vocacional, empreendedorismo, empregabilidade',1),
(10,23,1,'Plataforma Conexa (LMS interno)','Digital (EAD)','Colaboradores e comunidades do entorno','Interno / parcialmente aberto','Capacitações em: jogos, filmes, conteúdos TED, parcerias com universidades nacionais e internacionais; foco em habilidades digitais e segurança',1),
