INSERT INTO sector_fato_atlas (id,sector_id,atlas_name,nota) VALUES
(1,1,'Atlas de Soldagem e Metalurgia v1.0','Diretamente aplicável: soldagem estrutural em mineração, inspeção de equipamentos, caldeiraria'),
(2,1,'Atlas de Petroquímica v1.0','Parcialmente aplicável: automação de processos, instrumentação, segurança industrial'),
(3,2,'Atlas de Soldagem e Metalurgia v1.0','O Atlas mais diretamente alinhado com este setor. Cobre todos os processos de soldagem industrial, metalurgia, inspeção END e qualificação de procedimentos'),
(4,2,'Atlas de Petroquímica v1.0','Aplicável para automação industrial e instrumentação de processos siderúrgicos modernos'),
(5,3,'Atlas de Petroquímica v1.0','Atlas principal para este setor. 33 trilhas, 18 perfis profissionais, do operador de planta ao especialista sênior'),
(6,3,'Atlas de Soldagem e Metalurgia v1.0','Para a vertical de inspeção, integridade e manutenção industrial'),
(7,4,'Atlas de Petroquímica v1.0','Aplicável para automação de processos contínuos, instrumentação, segurança e operação de utilidades (vapor, águas industriais) — competências diretamente transferíveis a fábricas de celulose'),
(8,4,'Atlas de Soldagem e Metalurgia v1.0','Aplicável para manutenção industrial: soldagem em equipamentos de processo, inspeção END de vasos de pressão e caldeiras'),
(9,5,'Atlas de Petroquímica v1.1','O Atlas mais diretamente aplicável: processos químicos, segurança industrial, instrumentação, controle de processos e refinaria. Praticamente todas as competências cobrem química industrial de processo contínuo.'),
(10,6,'Atlas de Petroquímica v1.1','Trilhas A6 (equipamentos rotativos), A3 (automação) e UC 12 (manutenção industrial) são diretamente aplicáveis à manutenção de máquinas industriais'),
(11,6,'Atlas de Soldagem e Metalurgia v1.0','Para a fabricação e manutenção de estruturas metálicas em máquinas pesadas'),
(12,7,'Atlas de Petroquímica v1.1','Competências transferíveis: automação, manutenção industrial, instrumentação; aplicáveis a fábricas automotivas (linha de montagem automatizada) e a sistemas de combustível/lubrificação veicular'),
(13,8,'Atlas de Petroquímica v1.1','Trilhas de automação de processos contínuos (A3, D3, D5) e instrumentação (A2, UC 6) são diretamente transferíveis para processos alimentares. A lógica de operação é a mesma: processos contínuos com controle de temperatura, pressão e fluxo.'),
(14,9,'Atlas de Petroquímica v1.1','Automação de processos contínuos, manutenção industrial (A6, UC 12) e segurança em ambientes industriais (A4) são competências 100% transferíveis para plantas de cimento e minerais'),
(15,11,'Atlas de Soldagem e Metalurgia v1.0','O Atlas mais diretamente alinhado com este setor. Cobre desde os processos básicos de soldagem até qualificação de inspetores e especificação de procedimentos'),
(16,11,'Atlas de Petroquímica v1.1','Para a componente de automação e instrumentação em projetos de montagem industrial (EPC)');
